import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) sīra: sources and their criticism, disputed chronology and counts, the sound reports behind major events, and the classical works. Draft content, needs scholarly review.
export const QS: RawQ[] = [
{ id: "xsr-001", s: "seerah", g: 4, d: 6, t: ["sources", "ibn-ishaq"], src: "Ibn Hishām, al-Sīra al-Nabawiyya; Ibn Isḥāq as cited by al-Ṭabarī, Taʾrīkh; al-Dhahabī, Siyar Aʿlām al-Nubalāʾ",
    en: ["How has Ibn Isḥāq’s Sīra reached us, and how did scholars regard him?", ["Through the recension of Ibn Hishām, who edited it from the transmission of Ziyād al-Bakkāʾī; scholars praised him in maghāzī but some, like Mālik, criticised him, and hadith critics were more cautious about his lone reports on legal matters", "Through a manuscript he wrote himself in the Prophet’s lifetime", "Through the recension of al-Bukhārī", "It has not survived at all in any form"], "Muḥammad ibn Isḥāq (d. c. 150 AH) wrote the earliest comprehensive biography. His book survives in the edited recension of Ibn Hishām (d. c. 218 AH), who omitted and added material, and in quotations, notably in al-Ṭabarī. Al-Zuhrī praised his knowledge of the maghāzī, and some hadith critics accepted him in that field but were cautious in rulings and criticised his tadlīs; Mālik is reported to have been harsh on him."],
    de: ["Wie ist Ibn Isḥāqs Sīra zu uns gelangt, und wie beurteilten ihn die Gelehrten?", ["Durch die Rezension von Ibn Hišām, der sie nach der Überlieferung von Ziyād al-Bakkāʾī bearbeitete; Gelehrte lobten ihn in den Maġāzī, einige wie Mālik kritisierten ihn, und Hadithkritiker waren bei seinen Einzelberichten zu Rechtsfragen vorsichtiger", "Durch ein von ihm selbst zu Lebzeiten des Propheten geschriebenes Manuskript", "Durch die Rezension von al-Buḫārī", "Sie ist in keiner Form erhalten"], "Muḥammad ibn Isḥāq (gest. um 150 n. H.) schrieb die früheste umfassende Biografie. Sein Buch ist in der bearbeiteten Rezension von Ibn Hišām (gest. um 218 n. H.) erhalten, der Stoff ausließ und hinzufügte, und in Zitaten, vor allem bei aṭ-Ṭabarī. Az-Zuhrī lobte sein Wissen in den Maġāzī, und manche Hadithkritiker nahmen ihn auf diesem Gebiet an, waren aber bei Rechtsurteilen vorsichtig und kritisierten seinen Tadlīs; von Mālik wird berichtet, er sei hart mit ihm gewesen."],
    ar: ["كيف وصلتنا سيرة ابن إسحاق وكيف حكم العلماء عليه؟", ["عبر تهذيب ابن هشام من رواية زياد البكائي، وأثنى العلماء عليه في المغازي وانتقده بعضهم كمالك وتحفظ نقاد الحديث في تفرداته في الأحكام", "عبر مخطوط كتبه بنفسه في حياة النبي ﷺ", "عبر رواية البخاري", "لم تصل بأي صورة"], "كتب محمد بن إسحاق (ت نحو 150هـ) أقدم سيرة شاملة، ووصل كتابه في تهذيب ابن هشام (ت نحو 218هـ) الذي حذف منه وزاد وفي نقول أبرزها عند الطبري، وأثنى الزهري على علمه بالمغازي، وقبله بعض النقاد في هذا الباب مع التحفظ في الأحكام ونقد تدليسه، ويُروى أن مالكًا كان شديدًا عليه."] },

  { id: "xsr-002", s: "seerah", g: 4, d: 7, t: ["sources", "maghazi-musa-ibn-uqba"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ; Ibn Ḥajar, Tahdhīb al-Tahdhīb; al-Bayhaqī, Dalāʾil al-Nubuwwa",
    en: ["Whose Maghāzī was considered by some early scholars to be the most reliable work on the campaigns, and who transmitted from him?", ["Mūsā ibn ʿUqba (d. 141 AH), a student of al-Zuhrī, whose work survives only in fragments and quotations", "Ibn al-Jawzī, in the 6th century AH", "Al-Wāqidī, whose work was praised by all hadith critics", "Ibn Kathīr, in the 8th century AH"], "Mūsā ibn ʿUqba, a freedman of the family of al-Zubayr and a student of al-Zuhrī, wrote a Maghāzī that Mālik is reported to have recommended as the most reliable. Only fragments and quotations survive (for example in al-Bayhaqī’s Dalāʾil al-Nubuwwa). It contrasts with al-Wāqidī’s large Maghāzī, which is rich in detail but criticised as a source by hadith critics."],
    de: ["Wessen Maġāzī galt manchen frühen Gelehrten als das zuverlässigste Werk über die Feldzüge, und wer überlieferte von ihm?", ["Mūsā ibn ʿUqba (gest. 141 n. H.), ein Schüler az-Zuhrīs, dessen Werk nur in Fragmenten und Zitaten erhalten ist", "Ibn al-Ǧauzī im 6. Jh. n. H.", "Al-Wāqidī, dessen Werk von allen Hadithkritikern gelobt wurde", "Ibn Kaṯīr im 8. Jh. n. H."], "Mūsā ibn ʿUqba, ein Freigelassener der Familie az-Zubair und Schüler az-Zuhrīs, schrieb ein Maġāzī, das Mālik laut Bericht als das zuverlässigste empfahl. Nur Fragmente und Zitate sind erhalten (etwa in al-Baihaqīs Dalāʾil an-Nubuwwa). Es steht im Gegensatz zu al-Wāqidīs großem Maġāzī, das reich an Einzelheiten ist, aber von Hadithkritikern als Quelle kritisiert wurde."],
    ar: ["مغازي من عدّها بعض المتقدمين أصح الكتب في الغزوات ومن روى عنه؟", ["موسى بن عقبة (ت 141هـ) تلميذ الزهري، ولم يصل كتابه إلا شذرات ونقولًا", "ابن الجوزي في القرن السادس الهجري", "الواقدي الذي أثنى عليه كل نقاد الحديث", "ابن كثير في القرن الثامن الهجري"], "موسى بن عقبة مولى آل الزبير وتلميذ الزهري ألّف «المغازي» ويُروى أن مالكًا أوصى به لأنه أصح المغازي، ولم يصل إلا شذرات ونقول (كما في «دلائل النبوة» للبيهقي)، وهو بخلاف «مغازي» الواقدي الكبيرة الغنية بالتفصيل لكن انتقدها نقاد الحديث."] },

  { id: "xsr-003", s: "seerah", g: 4, d: 6, t: ["sources", "waqidi-ibn-sad"], src: "Ibn Saʿd, al-Ṭabaqāt al-Kubrā; al-Wāqidī, al-Maghāzī; al-Dhahabī, Siyar Aʿlām al-Nubalāʾ",
    en: ["What is the relation of al-Wāqidī to Ibn Saʿd, and how is each regarded?", ["Ibn Saʿd (d. 230 AH) was his scribe (kātib al-Wāqidī) and drew heavily on his material in al-Ṭabaqāt al-Kubrā; Ibn Saʿd is regarded as trustworthy and al-Wāqidī as a weak narrator though valued for historical detail", "Ibn Saʿd was his teacher and rejected his work", "They were the same person", "Ibn Saʿd lived in the Prophet’s time"], "Ibn Saʿd was called ‘scribe of al-Wāqidī’ because he took heavily from him, and from other sources, in his Ṭabaqāt, an early biographical work on the Prophet, Companions and Successors. Hadith scholars considered al-Wāqidī weak as a narrator of hadith (some called him matrūk), though historians continue to use his detail on campaigns with caution. Ibn Saʿd himself is generally considered trustworthy."],
    de: ["In welchem Verhältnis steht al-Wāqidī zu Ibn Saʿd, und wie wird jeder beurteilt?", ["Ibn Saʿd (gest. 230 n. H.) war sein Schreiber (kātib al-Wāqidī) und schöpfte reichlich aus seinem Stoff in aṭ-Ṭabaqāt al-Kubrā; Ibn Saʿd gilt als vertrauenswürdig, al-Wāqidī als schwacher Überlieferer, aber wertvoll für historische Einzelheiten", "Ibn Saʿd war sein Lehrer und lehnte sein Werk ab", "Sie waren dieselbe Person", "Ibn Saʿd lebte zur Zeit des Propheten"], "Ibn Saʿd wurde ‚Schreiber al-Wāqidīs‘ genannt, weil er in seinen Ṭabaqāt, einem frühen biografischen Werk über den Propheten, die Gefährten und die Nachfolger, viel von ihm und aus anderen Quellen nahm. Hadithgelehrte hielten al-Wāqidī als Hadithüberlieferer für schwach (manche nannten ihn matrūk), obwohl Historiker seine Einzelheiten zu Feldzügen mit Vorsicht weiter nutzen. Ibn Saʿd selbst gilt allgemein als vertrauenswürdig."],
    ar: ["ما صلة الواقدي بابن سعد وكيف يُنظر إلى كل منهما؟", ["ابن سعد (ت 230هـ) كاتب الواقدي وأكثر النقل عنه في «الطبقات الكبرى»، وابن سعد ثقة والواقدي ضعيف الرواية لكن يُنتفع بتفاصيله التاريخية", "ابن سعد كان شيخه وردّ كتابه", "هما شخص واحد", "عاش ابن سعد في زمن النبي ﷺ"], "لُقّب ابن سعد كاتب الواقدي لإكثاره النقل عنه وعن غيره في «الطبقات» وهو كتاب مبكر في تراجم النبي ﷺ والصحابة والتابعين، وضعّف المحدثون الواقدي في الرواية (وسماه بعضهم متروكًا) مع انتفاع المؤرخين بتفاصيله في المغازي بحذر، وابن سعد نفسه ثقة عمومًا."] },

  { id: "xsr-004", s: "seerah", g: 4, d: 7, t: ["chronology", "birth", "year-of-elephant"], src: "Ibn Isḥāq as in Ibn Hishām, al-Sīra; al-Ṭabarī, Taʾrīkh; Ibn Kathīr, al-Bidāya wa-l-Nihāya",
    en: ["How do the classical sources relate the Prophet’s birth to the Year of the Elephant, and what differences are noted?", ["Most placed his birth in the Year of the Elephant, in the month of Rabīʿ al-Awwal, with differing opinions on the day (the second, eighth, tenth or twelfth being cited); the twelfth is most widespread in popular practice", "Most placed it ten years before the Year of the Elephant, in Ramadan", "All agreed on one specific day with no differences", "Most placed it after the Hijra"], "Most scholars followed Ibn Isḥāq in saying he ﷺ was born in the Year of the Elephant, in Rabīʿ al-Awwal. As for the day, the sources record the second, eighth, tenth and twelfth, and the twelfth is the best-known in practice. Some scholars (such as the astronomer Maḥmūd Pasha al-Falakī in modern times) computed a ninth date, but the classical sources do not agree."],
    de: ["Wie setzen die klassischen Quellen die Geburt des Propheten zum Elefantenjahr in Beziehung, und welche Unterschiede werden vermerkt?", ["Die meisten setzten seine Geburt ins Elefantenjahr im Monat Rabīʿ al-Awwal, mit unterschiedlichen Meinungen zum Tag (genannt werden der zweite, achte, zehnte oder zwölfte); der zwölfte ist in der Volkspraxis am verbreitetsten", "Die meisten setzten sie zehn Jahre vor das Elefantenjahr, im Ramadan", "Alle waren sich ohne Unterschiede auf einen bestimmten Tag einig", "Die meisten setzten sie nach der Hidschra"], "Die meisten Gelehrten folgten Ibn Isḥāq und sagten, er ﷺ sei im Elefantenjahr im Rabīʿ al-Awwal geboren. Zum Tag verzeichnen die Quellen den zweiten, achten, zehnten und zwölften, und der zwölfte ist in der Praxis am bekanntesten. Manche Gelehrte (wie in neuerer Zeit der Astronom Maḥmūd Pascha al-Falakī) berechneten ein neuntes Datum, doch die klassischen Quellen stimmen nicht überein."],
    ar: ["كيف تربط المصادر الكلاسيكية مولد النبي ﷺ بعام الفيل وما الاختلافات المذكورة؟", ["رجح الأكثر أنه وُلد عام الفيل في ربيع الأول مع اختلاف في اليوم (الثاني أو الثامن أو العاشر أو الثاني عشر) والثاني عشر أشهرها في العمل", "رجح الأكثر أنه قبل عام الفيل بعشر سنين في رمضان", "اتفق الجميع على يوم محدد بلا خلاف", "رجح الأكثر أنه بعد الهجرة"], "تابع أكثر العلماء ابن إسحاق في أنه ﷺ وُلد عام الفيل في ربيع الأول، وفي اليوم أقوال: الثاني والثامن والعاشر والثاني عشر، والثاني عشر أشهرها في العمل، وحسب بعض المحدثين كمحمود باشا الفلكي تاريخًا تاسعًا، والمصادر الكلاسيكية لا تتفق."] },

  { id: "xsr-005", s: "seerah", g: 4, d: 6, t: ["childhood", "halima", "banu-sad"], src: "Ibn Hishām, al-Sīra al-Nabawiyya; Ibn Saʿd, al-Ṭabaqāt al-Kubrā; Muslim, Ṣaḥīḥ, Kitāb al-īmān (shaqq al-ṣadr)",
    en: ["Who nursed the Prophet ﷺ in his infancy, and which event is reported from his time with her tribe?", ["Ḥalīma al-Saʿdiyya of Banū Saʿd; the splitting of his chest (shaqq al-ṣadr) is reported in a sound report in Muslim", "Umm Ayman, in Madīna; the opening of Makka", "Khadīja, in Makka; the first revelation", "Fāṭima, in Madīna; the migration"], "In Arab custom children were sent to the desert tribes. The Prophet ﷺ was nursed by Ḥalīma bint Abī Dhuʾayb of Banū Saʿd ibn Bakr, and stayed with her until about the age of four or five. A report in Ṣaḥīḥ Muslim from Anas describes how Jibrīl opened his chest and washed his heart, an event placed in this period by the sources, although some authors differ over the time."],
    de: ["Wer stillte den Propheten ﷺ als Säugling, und welches Ereignis wird aus seiner Zeit beim Stamm der Amme berichtet?", ["Ḥalīma as-Saʿdiyya von den Banū Saʿd; die Öffnung seiner Brust (šaqq aṣ-ṣadr) wird in einem gesunden Bericht bei Muslim überliefert", "Umm Aiman in Medina; die Öffnung Mekkas", "Ḫadīǧa in Mekka; die erste Offenbarung", "Fāṭima in Medina; die Auswanderung"], "Nach arabischem Brauch wurden Kinder zu den Wüstenstämmen gegeben. Der Prophet ﷺ wurde von Ḥalīma bint Abī Ḏuʾaib von den Banū Saʿd ibn Bakr gestillt und blieb bei ihr bis etwa zum Alter von vier oder fünf Jahren. Ein Bericht in Ṣaḥīḥ Muslim von Anas beschreibt, wie Ǧibrīl seine Brust öffnete und sein Herz wusch, ein Ereignis, das die Quellen in diese Zeit setzen, obwohl manche Autoren über den Zeitpunkt abweichen."],
    ar: ["من أرضعت النبي ﷺ في طفولته وما الحادثة المروية من إقامته عند قبيلتها؟", ["حليمة السعدية من بني سعد، وشق الصدر ثابت في رواية صحيحة عند مسلم", "أم أيمن في المدينة، وفتح مكة", "خديجة في مكة، ونزول الوحي", "فاطمة في المدينة، والهجرة"], "كانت العرب تسترضع أولادها في البوادي، فأرضعت النبيَّ ﷺ حليمة بنت أبي ذؤيب من بني سعد بن بكر وبقي عندها إلى نحو الرابعة أو الخامسة، وفي صحيح مسلم عن أنس أن جبريل شق صدره وغسل قلبه، وتجعل المصادر هذه الحادثة في تلك المدة وإن اختلف بعضهم في وقتها."] },

  { id: "xsr-006", s: "seerah", g: 4, d: 6, t: ["pre-prophecy", "hilf-al-fudul"], src: "Ibn Hishām, al-Sīra al-Nabawiyya; Ibn Kathīr, al-Bidāya wa-l-Nihāya; al-Suhaylī, al-Rawḍ al-Unuf",
    en: ["What was the Ḥilf al-Fuḍūl, and what is reported of the Prophet’s attitude to it after prophecy?", ["A pact of Makkan clans to support the wronged in Makka, which the Prophet ﷺ attended in his youth and later said he would respond to if called to it in Islam", "A treaty with the Byzantines to protect trade", "A pact among poets for contests at ʿUkāẓ", "A treaty with Madīna signed after the Hijra"], "The Ḥilf al-Fuḍūl was a covenant among some Makkan clans in the house of ʿAbd Allāh ibn Judʿān to give justice to the wronged, whoever they were. The Prophet ﷺ is reported to have said he witnessed it in the house of Ibn Judʿān and would not exchange it for red camels, and that if invited to it in Islam he would respond. The report is cited in Ibn Hishām and in other works, with discussion about its chain."],
    de: ["Was war der Ḥilf al-Fuḍūl, und was wird über die Haltung des Propheten dazu nach der Prophetie berichtet?", ["Ein Bund mekkanischer Sippen zur Unterstützung der Unrecht Erleidenden in Mekka, dem der Prophet ﷺ in seiner Jugend beiwohnte und zu dem er später sagte, er würde darauf antworten, wenn er im Islam dazu gerufen würde", "Ein Vertrag mit den Byzantinern zum Handelsschutz", "Ein Bund unter Dichtern für Wettstreite in ʿUkāẓ", "Ein nach der Hidschra mit Medina geschlossener Vertrag"], "Der Ḥilf al-Fuḍūl war ein Bündnis einiger mekkanischer Sippen im Haus von ʿAbd Allāh ibn Ǧudʿān, dem Unrecht Erleidenden Gerechtigkeit zu verschaffen, wer immer sie seien. Vom Propheten ﷺ wird berichtet, er habe ihn im Haus von Ibn Ǧudʿān miterlebt und würde ihn nicht gegen rote Kamele tauschen, und wenn er im Islam dazu eingeladen würde, würde er antworten. Der Bericht wird bei Ibn Hišām und in anderen Werken angeführt, mit Erörterung seiner Kette."],
    ar: ["ما حلف الفضول وما المروي عن موقف النبي ﷺ منه بعد البعثة؟", ["تعاهد بين بطون قريش لنصرة المظلوم في مكة شهده النبي ﷺ في شبابه وقال لاحقًا إنه لو دُعي إليه في الإسلام لأجاب", "معاهدة مع الروم لحماية التجارة", "حلف بين الشعراء للمسابقات في عكاظ", "معاهدة مع المدينة بعد الهجرة"], "كان حلف الفضول عهدًا بين بعض بطون قريش في دار عبد الله بن جدعان على نصرة المظلوم أيًّا كان، ويُروى أن النبي ﷺ قال إنه شهد في دار ابن جدعان حلفًا ما يسرّه به حمر النعم ولو دُعي به في الإسلام لأجاب، وذكره ابن هشام وغيره مع كلام في إسناده."] },

  { id: "xsr-007", s: "seerah", g: 4, d: 7, t: ["revelation", "first-revelation", "waraqa"], src: "al-Bukhārī, Ṣaḥīḥ, Bad’ al-waḥy; Muslim, Ṣaḥīḥ, Kitāb al-īmān; Ibn Ḥajar, Fatḥ al-Bārī",
    en: ["Which report is the main source on the beginning of revelation, and what is debated about the period after it (fatrat al-waḥy)?", ["The report of ʿĀʾisha in al-Bukhārī and Muslim (the true dreams, Ḥirāʾ, and Waraqa); the length of the pause is disputed, and its wording in the account of Jābir ibn ʿAbd Allāh is the basis for the descent of the verses of al-Muddaththir", "The report of Abū Hurayra on the day of Badr", "The report of Anas on the Night Journey", "The report of Ibn ʿAbbās on the farewell sermon"], "ʿĀʾisha’s long report in the first chapter of al-Bukhārī gives the true dream, seclusion in Ḥirāʾ, the first descent of Jibrīl and the visit to Waraqa ibn Nawfal. The pause of revelation that followed is reported in the account of Jābir, who relates the descent of the verses of al-Muddaththir after it. The length of the pause is differently reported, the figures of two and a half years or three years in some reports being weak or disputed."],
    de: ["Welcher Bericht ist die Hauptquelle zum Beginn der Offenbarung, und was ist über die anschließende Pause (fatrat al-waḥy) umstritten?", ["Der Bericht ʿĀʾišas bei al-Buḫārī und Muslim (die wahren Träume, Ḥirāʾ und Waraqa); die Länge der Pause ist umstritten, und der Bericht von Ǧābir ibn ʿAbd Allāh ist die Grundlage für die Herabsendung der Verse von al-Muddaṯṯir", "Der Bericht Abū Hurairas über den Tag von Badr", "Der Bericht des Anas über die Nachtreise", "Der Bericht Ibn ʿAbbās’ über die Abschiedspredigt"], "ʿĀʾišas langer Bericht im ersten Kapitel von al-Buḫārī nennt den wahren Traum, die Abgeschiedenheit in Ḥirāʾ, das erste Herabkommen Ǧibrīls und den Besuch bei Waraqa ibn Naufal. Die anschließende Offenbarungspause wird im Bericht Ǧābirs erzählt, der die Herabsendung der Verse von al-Muddaṯṯir danach schildert. Die Länge der Pause wird unterschiedlich berichtet, wobei die Angaben von zweieinhalb oder drei Jahren in manchen Berichten schwach oder umstritten sind."],
    ar: ["أي رواية هي المصدر الرئيس لبدء الوحي وما المختلف فيه من مدة فتور الوحي؟", ["حديث عائشة في البخاري ومسلم (الرؤيا الصادقة وحراء وورقة)، ومدة الفترة مختلف فيها، وحديث جابر هو أساس نزول آيات المدثر بعدها", "حديث أبي هريرة عن يوم بدر", "حديث أنس عن الإسراء", "حديث ابن عباس عن خطبة الوداع"], "يذكر حديث عائشة الطويل في أول صحيح البخاري الرؤيا الصادقة والخلوة في حراء ونزول جبريل أول مرة ولقاء ورقة بن نوفل، وفترة الوحي بعده مذكورة في حديث جابر الذي يروي نزول آيات المدثر بعدها، وتختلف الروايات في مدتها ومن ذكر سنتين ونصفًا أو ثلاثًا ففي روايته ضعف أو خلاف."] },

  { id: "xsr-008", s: "seerah", g: 4, d: 6, t: ["dawah", "early-converts"], src: "Ibn Hishām, al-Sīra; Ibn Saʿd, al-Ṭabaqāt; al-Ṭabarī, Taʾrīkh; al-Tirmidhī, Jāmiʿ (on first Muslims)",
    en: ["How do classical sources describe the first people to accept Islam, and what is debated?", ["Khadīja among women, Abū Bakr among free adult men, ʿAlī among children and Zayd ibn Ḥāritha among freedmen are commonly named; scholars reconciled the claims by dividing them into categories", "Only ʿUmar and ʿUthmān are named", "All sources agree that Abū Lahab was first", "No source mentions the first Muslims"], "There are reports that ‘the first to believe’ was Khadīja, Abū Bakr, ʿAlī or Zayd. Scholars such as Ibn Isḥāq and al-Ṭabarī reconcile them: Khadīja was the first of all, Abū Bakr the first free man, ʿAlī the first child and Zayd the first freedman. Others included Bilāl and ʿAmmār. This approach is common in Ibn Kathīr’s treatment."],
    de: ["Wie beschreiben klassische Quellen die ersten, die den Islam annahmen, und was ist umstritten?", ["Ḫadīǧa unter den Frauen, Abū Bakr unter den freien erwachsenen Männern, ʿAlī unter den Kindern und Zaid ibn Ḥāriṯa unter den Freigelassenen werden meist genannt; Gelehrte vereinbarten die Angaben durch Einteilung in Kategorien", "Nur ʿUmar und ʿUṯmān werden genannt", "Alle Quellen stimmen überein, dass Abū Lahab der erste war", "Keine Quelle erwähnt die ersten Muslime"], "Es gibt Berichte, wonach der ‚erste Gläubige‘ Ḫadīǧa, Abū Bakr, ʿAlī oder Zaid war. Gelehrte wie Ibn Isḥāq und aṭ-Ṭabarī vereinbaren sie: Ḫadīǧa war die erste von allen, Abū Bakr der erste freie Mann, ʿAlī das erste Kind und Zaid der erste Freigelassene. Andere nannten auch Bilāl und ʿAmmār. Dieser Ansatz ist bei Ibn Kaṯīr üblich."],
    ar: ["كيف تصف المصادر الكلاسيكية أوائل من أسلم وما المختلف فيه؟", ["تُذكر خديجة من النساء وأبو بكر من الرجال الأحرار وعلي من الصبيان وزيد بن حارثة من الموالي، وجمع العلماء الأقوال بتقسيمها إلى فئات", "لا يُذكر إلا عمر وعثمان", "تتفق المصادر كلها على أن أبا لهب أول من أسلم", "لا تذكر المصادر أوائل المسلمين"], "رُوي أن أول من آمن خديجة أو أبو بكر أو علي أو زيد، وجمع بينها ابن إسحاق والطبري وغيرهما فقالوا: خديجة أول الجميع وأبو بكر أول الأحرار وعلي أول الصبيان وزيد أول الموالي، وذُكر بلال وعمار، وهذا النهج شائع في عرض ابن كثير."] },

  { id: "xsr-009", s: "seerah", g: 4, d: 7, t: ["abyssinia", "hijra-first", "najashi"], src: "Ibn Hishām, al-Sīra; Aḥmad, Musnad (account of Umm Salama); Ibn Kathīr, al-Bidāya wa-l-Nihāya",
    en: ["Which report preserves the account of the first Hijra to Abyssinia, including the speech of Jaʿfar ibn Abī Ṭālib to the Negus?", ["The report of Umm Salama in Musnad Aḥmad and in Ibn Isḥāq, in which Jaʿfar explains Islam and recites from the sūra of Maryam", "The report of Abū Hurayra in Muslim on the Night Journey", "The report of ʿUmar on the treaty of Ḥudaybiya", "The report of Anas on the Battle of Uḥud"], "Umm Salama, who was among the emigrants, narrated how Quraysh sent ʿAmr ibn al-ʿĀṣ and ʿAbd Allāh ibn Abī Rabīʿa to the Negus to ask for the return of the Muslims, and how Jaʿfar answered by describing the Jāhiliyya and the message of the Prophet ﷺ and by reciting the beginning of sūrat Maryam. The account is in Aḥmad’s Musnad and in Ibn Isḥāq, with a chain regarded as good."],
    de: ["Welcher Bericht bewahrt die Schilderung der ersten Hidschra nach Abessinien, einschließlich der Rede Ǧaʿfar ibn Abī Ṭālibs vor dem Negus?", ["Der Bericht Umm Salamas im Musnad Aḥmad und bei Ibn Isḥāq, in dem Ǧaʿfar den Islam erklärt und aus der Sure Maryam rezitiert", "Der Bericht Abū Hurairas bei Muslim über die Nachtreise", "Der Bericht ʿUmars über den Vertrag von Ḥudaibiya", "Der Bericht des Anas über die Schlacht von Uḥud"], "Umm Salama, die zu den Auswanderern gehörte, erzählte, wie Quraiš ʿAmr ibn al-ʿĀṣ und ʿAbd Allāh ibn Abī Rabīʿa zum Negus schickten, um die Rückgabe der Muslime zu fordern, und wie Ǧaʿfar antwortete, indem er die Ǧāhiliyya und die Botschaft des Propheten ﷺ beschrieb und den Anfang der Sure Maryam rezitierte. Der Bericht steht in Aḥmads Musnad und bei Ibn Isḥāq mit einer als gut geltenden Kette."],
    ar: ["أي رواية تحفظ قصة الهجرة الأولى إلى الحبشة ومنها كلام جعفر بن أبي طالب للنجاشي؟", ["رواية أم سلمة في مسند أحمد وعند ابن إسحاق وفيها شرح جعفر للإسلام وتلاوته من سورة مريم", "رواية أبي هريرة في مسلم عن الإسراء", "رواية عمر عن صلح الحديبية", "رواية أنس عن غزوة أحد"], "روت أم سلمة وكانت من المهاجرين كيف أرسلت قريش عمرو بن العاص وعبد الله بن أبي ربيعة إلى النجاشي ليردّ المسلمين، وكيف أجاب جعفر فوصف الجاهلية ورسالة النبي ﷺ وتلا صدر سورة مريم، والقصة في مسند أحمد وعند ابن إسحاق بإسناد يُعد حسنًا."] },

  { id: "xsr-010", s: "seerah", g: 4, d: 6, t: ["boycott", "shib-abi-talib"], src: "Ibn Hishām, al-Sīra; Ibn Saʿd, al-Ṭabaqāt; al-Bukhārī, Ṣaḥīḥ, Kitāb al-manāqib (mention of al-Muḥaṣṣab)",
    en: ["What was the boycott of the Prophet’s clan in Shiʿb Abī Ṭālib, and how did the sources say it ended?", ["Quraysh wrote a document boycotting Banū Hāshim and Banū al-Muṭṭalib; the sources say it lasted about two to three years and ended when some Makkans, including Hishām ibn ʿAmr and Zuhayr ibn Abī Umayya, worked to cancel it", "Quraysh banned the Muslims from fasting; it ended with the Hijra", "The Romans blocked the road; it ended with Mu’ta", "Madīna closed its markets; it ended at Badr"], "Quraysh wrote a pact against Banū Hāshim and Banū al-Muṭṭalib to prevent marriage and trade with them until they handed over the Prophet ﷺ, and hung it in the Kaʿba. The clans stayed in the glen of Abū Ṭālib. The sources give the duration as two or three years, and tell that some Makkans, such as Hishām ibn ʿAmr and Zuhayr, led an effort to annul it, and that the pact was found eaten by termites except the Name of God."],
    de: ["Was war der Boykott der Sippe des Propheten in Šiʿb Abī Ṭālib, und wie endete er nach den Quellen?", ["Quraiš schrieb eine Urkunde zum Boykott der Banū Hāšim und Banū al-Muṭṭalib; die Quellen nennen etwa zwei bis drei Jahre Dauer, und er endete, als einige Mekkaner, darunter Hišām ibn ʿAmr und Zuhair ibn Abī Umayya, sich für die Aufhebung einsetzten", "Quraiš verbot den Muslimen das Fasten; er endete mit der Hidschra", "Die Römer sperrten die Straße; er endete bei Muʾta", "Medina schloss seine Märkte; er endete bei Badr"], "Quraiš schrieb ein Abkommen gegen die Banū Hāšim und Banū al-Muṭṭalib, um Heirat und Handel mit ihnen zu verhindern, bis sie den Propheten ﷺ auslieferten, und hängte es in der Kaaba auf. Die Sippen blieben in der Schlucht Abū Ṭālibs. Die Quellen nennen zwei oder drei Jahre Dauer und erzählen, einige Mekkaner wie Hišām ibn ʿAmr und Zuhair hätten die Aufhebung betrieben und das Abkommen sei von Termiten gefressen gefunden worden bis auf den Namen Gottes."],
    ar: ["ما مقاطعة بني هاشم في شعب أبي طالب وكيف انتهت بحسب المصادر؟", ["كتبت قريش صحيفة بمقاطعة بني هاشم وبني المطلب، ومدتها نحو سنتين أو ثلاث، وانتهت لما سعى بعض أهل مكة كهشام بن عمرو وزهير بن أبي أمية في نقضها", "منعت قريش المسلمين من الصيام وانتهت بالهجرة", "حاصر الروم الطريق وانتهت بمؤتة", "أغلقت المدينة أسواقها وانتهت ببدر"], "كتبت قريش صحيفة ضد بني هاشم وبني المطلب بمنع المصاهرة والمبايعة حتى يسلموا النبي ﷺ وعلقتها في الكعبة، فأقام بنو هاشم في شعب أبي طالب، وتقدّر المصادر المدة بسنتين أو ثلاث، وتذكر أن بعض أهل مكة كهشام بن عمرو وزهير سعوا في نقضها وأن الأرضة أكلت الصحيفة إلا اسم الله."] },

  { id: "xsr-011", s: "seerah", g: 4, d: 7, t: ["year-of-sorrow", "taif"], src: "Ibn Hishām, al-Sīra; al-Bukhārī, Ṣaḥīḥ (ʿĀʾisha on al-Ṭāʾif, Bad’ al-khalq); Ibn Saʿd, al-Ṭabaqāt",
    en: ["What do the sources say about the Prophet’s journey to al-Ṭāʾif?", ["He went after Abū Ṭālib’s and Khadīja’s deaths to seek support from Thaqīf, was rejected and mistreated; ʿĀʾisha’s report in al-Bukhārī mentions the angel of the mountains who offered to crush Makka’s two mountains and the Prophet’s refusal", "He went to al-Ṭāʾif to marry and was welcomed", "He went to buy horses and returned in a week", "He went for ḥajj with the Companions after the conquest"], "After the deaths of Khadīja and Abū Ṭālib, the Prophet ﷺ went to al-Ṭāʾif to invite Thaqīf, but their leaders rejected him and urged their slaves and children to throw stones. Al-Bukhārī and Muslim record ʿĀʾisha’s question about the hardest day since Uḥud, with his reply about the trip and the offer of the angel of the mountains to crush the two mountains (al-Akhshabayn), which he declined, hoping for believers from their descendants."],
    de: ["Was sagen die Quellen über die Reise des Propheten nach aṭ-Ṭāʾif?", ["Er ging nach dem Tod Abū Ṭālibs und Ḫadīǧas, um bei Ṯaqīf Unterstützung zu suchen, wurde abgewiesen und misshandelt; ʿĀʾišas Bericht bei al-Buḫārī erwähnt den Engel der Berge, der anbot, die beiden Berge Mekkas zu zermalmen, und die Ablehnung des Propheten", "Er ging nach aṭ-Ṭāʾif, um zu heiraten, und wurde willkommen geheißen", "Er ging, um Pferde zu kaufen, und kehrte nach einer Woche zurück", "Er ging nach der Eroberung mit den Gefährten zum Ḥaǧǧ"], "Nach dem Tod Ḫadīǧas und Abū Ṭālibs ging der Prophet ﷺ nach aṭ-Ṭāʾif, um Ṯaqīf einzuladen, doch ihre Anführer wiesen ihn ab und hetzten ihre Sklaven und Kinder, Steine zu werfen. Al-Buḫārī und Muslim überliefern ʿĀʾišas Frage nach dem härtesten Tag seit Uḥud mit seiner Antwort über die Reise und das Angebot des Engels der Berge, die beiden Berge (al-Aḫšabain) zu zermalmen, was er ablehnte, in der Hoffnung auf Gläubige unter ihren Nachkommen."],
    ar: ["ماذا تقول المصادر عن رحلة النبي ﷺ إلى الطائف؟", ["خرج بعد وفاة أبي طالب وخديجة يلتمس نصرة ثقيف فرُدّ وأُوذي، وفي حديث عائشة في البخاري ملك الجبال الذي عرض إطباق الأخشبين ورفضه النبي ﷺ", "ذهب إلى الطائف ليتزوج فاستُقبل", "ذهب لشراء الخيل ورجع بعد أسبوع", "ذهب للحج مع الصحابة بعد الفتح"], "بعد وفاة خديجة وأبي طالب خرج النبي ﷺ إلى الطائف يدعو ثقيفًا فردّه سادتهم وأغروا به سفهاءهم وصبيانهم يرمونه بالحجارة، وفي الصحيحين سؤال عائشة عن أشد يوم لقيه بعد أحد وجوابه عن الطائف وعرض ملك الجبال أن يطبق الأخشبين فأبى أملًا في أن يخرج الله من أصلابهم من يوحده."] },

  { id: "xsr-012", s: "seerah", g: 4, d: 7, t: ["isra-miraj", "chronology-debate"], src: "Ibn Ḥajar, Fatḥ al-Bārī (Kitāb manāqib al-anṣār, bāb al-miʿrāj); Ibn Kathīr, Tafsīr, on sūrat al-Isrāʾ; al-Bukhārī and Muslim (Anas, Mālik ibn Ṣaʿṣaʿa)",
    en: ["What are the classical differences over the Isrāʾ and Miʿrāj regarding time and manner?", ["Reports differ on the date (before the Hijra by one year, or three or five years, in various months) and some scholars said it was one night while others split it into separate events; most Sunni scholars hold it was in body and soul, while a report from ʿĀʾisha and Muʿāwiya is cited for spirit only", "All reports agree on the same date and manner", "All reports say it happened in Madīna", "All reports place it after Badr"], "Ibn Ḥajar discusses the date, citing views from before the Hijra by one year, by eighteen months, by three or five years and others, and different months. Most hold the Isrāʾ and Miʿrāj was in one night and in body and soul, while a report attributed to ʿĀʾisha and Muʿāwiya says it was spiritual; the first is the dominant Sunni view, as Ibn Kathīr states."],
    de: ["Welche klassischen Unterschiede bestehen bei Isrāʾ und Miʿrāǧ hinsichtlich Zeit und Art?", ["Die Berichte unterscheiden sich im Datum (ein Jahr vor der Hidschra oder drei oder fünf Jahre, in verschiedenen Monaten), und manche Gelehrte sagten, es war eine Nacht, andere teilten es in getrennte Ereignisse; die meisten Sunniten halten es für leiblich und seelisch, während ein Bericht von ʿĀʾiša und Muʿāwiya für nur geistig angeführt wird", "Alle Berichte stimmen in Datum und Art überein", "Alle Berichte sagen, es geschah in Medina", "Alle Berichte setzen es nach Badr"], "Ibn Ḥaǧar erörtert das Datum und führt Ansichten an: ein Jahr, achtzehn Monate, drei oder fünf Jahre vor der Hidschra und andere sowie verschiedene Monate. Die meisten halten Isrāʾ und Miʿrāǧ für eine Nacht und leiblich und seelisch, während ein ʿĀʾiša und Muʿāwiya zugeschriebener Bericht sagt, es sei geistig gewesen; die erste ist die vorherrschende sunnitische Ansicht, wie Ibn Kaṯīr feststellt."],
    ar: ["ما الاختلافات الكلاسيكية في الإسراء والمعراج من حيث الزمان والكيفية؟", ["تختلف الروايات في وقته (قبل الهجرة بسنة أو ثلاث أو خمس في شهور متعددة) وفي كونه ليلة واحدة أو حدثين، والأكثر على أنه بالروح والجسد ويُنقل عن عائشة ومعاوية أنه بالروح", "تتفق الروايات كلها في الوقت والكيفية", "تقول الروايات كلها إنه وقع في المدينة", "تضعه الروايات كلها بعد بدر"], "ناقش ابن حجر وقت الإسراء وذكر أقوالًا بسنة قبل الهجرة وثمانية عشر شهرًا وثلاث أو خمس سنين وغيرها وشهورًا متعددة، والأكثر على أنهما في ليلة واحدة وبالروح والجسد، ويُنقل عن عائشة ومعاوية أنه بالروح، والأول هو المشهور عند أهل السنة كما يذكر ابن كثير."] },

  { id: "xsr-013", s: "seerah", g: 4, d: 6, t: ["aqaba", "ansar", "bay-a"], src: "Ibn Hishām, al-Sīra; Aḥmad, Musnad (Jābir on ʿAqaba); al-Ṭabarī, Taʾrīkh",
    en: ["How do the sources describe the two pledges of al-ʿAqaba?", ["The first in the year 12 of prophecy with twelve men and the second in the year 13 with about seventy-three men and two women, who pledged to protect him as they protected their families", "Both took place in Madīna in the year 2 AH", "The first with Quraysh and the second with Thaqīf", "Both took place in Ḥudaybiya"], "Ibn Isḥāq places the first pledge (with twelve men from Aws and Khazraj) in the twelfth year of prophecy and the second, in which seventy-three men and two women pledged to protect the Prophet ﷺ, in the thirteenth. Muṣʿab ibn ʿUmayr was sent to teach them. The details are in Ibn Hishām and in Aḥmad’s Musnad from Jābir, who was present."],
    de: ["Wie beschreiben die Quellen die beiden Treueide von al-ʿAqaba?", ["Der erste im Jahr 12 der Prophetie mit zwölf Männern und der zweite im Jahr 13 mit etwa dreiundsiebzig Männern und zwei Frauen, die schworen, ihn so zu schützen wie ihre Familien", "Beide fanden in Medina im Jahr 2 n. H. statt", "Der erste mit Quraiš und der zweite mit Ṯaqīf", "Beide fanden in Ḥudaibiya statt"], "Ibn Isḥāq setzt den ersten Treueid (mit zwölf Männern von Aus und Ḫazraǧ) ins zwölfte Jahr der Prophetie und den zweiten, in dem dreiundsiebzig Männer und zwei Frauen schworen, den Propheten ﷺ zu schützen, ins dreizehnte. Muṣʿab ibn ʿUmair wurde gesandt, sie zu lehren. Die Einzelheiten stehen bei Ibn Hišām und in Aḥmads Musnad von Ǧābir, der anwesend war."],
    ar: ["كيف تصف المصادر بيعتي العقبة؟", ["الأولى في السنة الثانية عشرة من البعثة باثني عشر رجلًا، والثانية في الثالثة عشرة بنحو ثلاثة وسبعين رجلًا وامرأتين بايعوا على حمايته كما يحمون أهليهم", "كلتاهما في المدينة سنة 2هـ", "الأولى مع قريش والثانية مع ثقيف", "كلتاهما في الحديبية"], "جعل ابن إسحاق البيعة الأولى (باثني عشر رجلًا من الأوس والخزرج) في السنة الثانية عشرة والثانية (بثلاثة وسبعين رجلًا وامرأتين على حماية النبي ﷺ) في الثالثة عشرة، وأرسل معهم مصعب بن عمير يعلمهم، والتفاصيل عند ابن هشام وفي مسند أحمد عن جابر وكان حاضرًا."] },

  { id: "xsr-014", s: "seerah", g: 4, d: 6, t: ["hijra", "route", "thawr"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb manāqib al-anṣār (ʿĀʾisha on the Hijra); Ibn Hishām, al-Sīra; Aḥmad, Musnad",
    en: ["According to ʿĀʾisha’s long report in al-Bukhārī, how did the Prophet ﷺ and Abū Bakr leave Makka?", ["They left at night from the back of Abū Bakr’s house, hid for three nights in the cave of Thawr, and ʿAbd Allāh ibn Urayqiṭ guided them by the coastal route", "They left openly by day with an armed escort", "They left by ship from Jidda", "They left with the caravan of Quraysh to Syria"], "ʿĀʾisha narrated how the Prophet ﷺ came to Abū Bakr’s house at midday, they left through a back window by night, hid in Thawr, with ʿAbd Allāh ibn Abī Bakr bringing news, ʿĀmir ibn Fuhayra the food and ʿAbd Allāh ibn Urayqiṭ (a non-Muslim guide, then still a polytheist) leading them along the coast. Surāqa ibn Mālik pursued them in the account."],
    de: ["Wie verließen der Prophet ﷺ und Abū Bakr Mekka nach ʿĀʾišas langem Bericht bei al-Buḫārī?", ["Sie verließen es nachts durch die Rückseite von Abū Bakrs Haus, versteckten sich drei Nächte in der Höhle Ṯaur, und ʿAbd Allāh ibn Uraiqiṭ führte sie auf der Küstenroute", "Sie verließen es offen am Tag mit bewaffneter Eskorte", "Sie fuhren mit dem Schiff von Dschidda", "Sie zogen mit der Karawane der Quraiš nach Syrien"], "ʿĀʾiša erzählte, wie der Prophet ﷺ mittags zu Abū Bakrs Haus kam, sie nachts durch ein Hinterfenster aufbrachen und sich in Ṯaur versteckten, wobei ʿAbd Allāh ibn Abī Bakr Nachrichten brachte, ʿĀmir ibn Fuhaira Essen und ʿAbd Allāh ibn Uraiqiṭ (ein damals noch heidnischer Führer) sie an der Küste entlangführte. Surāqa ibn Mālik verfolgte sie im Bericht."],
    ar: ["كيف خرج النبي ﷺ وأبو بكر من مكة بحسب حديث عائشة الطويل في البخاري؟", ["خرجا ليلًا من خوخة في ظهر بيت أبي بكر واختبآ ثلاث ليال في غار ثور وهداهما عبد الله بن أريقط في طريق الساحل", "خرجا علنًا نهارًا بحماية مسلحة", "خرجا بحرًا من جدة", "خرجا مع قافلة قريش إلى الشام"], "روت عائشة أن النبي ﷺ جاء بيت أبي بكر ظهرًا وخرجا ليلًا من خوخة خلفية واختبآ في ثور، يأتيهما عبد الله بن أبي بكر بالأخبار وعامر بن فهيرة بالطعام، وقادهما عبد الله بن أريقط (دليل كان على الشرك آنذاك) على طريق الساحل، وتتبعهما سراقة بن مالك في القصة."] },

  { id: "xsr-015", s: "seerah", g: 4, d: 7, t: ["madina", "sahifa", "constitution"], src: "Ibn Hishām, al-Sīra (the Ṣaḥīfa); Abū ʿUbayd, al-Amwāl; Ibn Kathīr, al-Bidāya wa-l-Nihāya; Ibn Isḥāq",
    en: ["What is the 'Ṣaḥīfa of Madīna' (often called its constitution), and how is it known?", ["A document of the early Madīnan period that regulated relations between the Emigrants, Anṣār and Jewish tribes, preserved in the Sīra of Ibn Isḥāq/Ibn Hishām and in Abū ʿUbayd’s al-Amwāl", "A poem by Ḥassān ibn Thābit", "A treaty with the Persians", "A fatwā of the caliph ʿUmar"], "The Ṣaḥīfa is a document attributed to the early period in Madīna that defines the Emigrants, the Anṣār and the Jews of Madīna as an ummah in terms of mutual defence and responsibilities. It is transmitted in Ibn Isḥāq (in Ibn Hishām) without a full chain and in Abū ʿUbayd’s al-Amwāl with a chain. Modern scholars dispute its dating and whether it was one or several documents."],
    de: ["Was ist die ‚Ṣaḥīfa von Medina‘ (oft ihre Verfassung genannt), und wie ist sie bekannt?", ["Ein Dokument der frühen medinensischen Zeit, das die Beziehungen zwischen Auswanderern, Anṣār und jüdischen Stämmen regelte, erhalten in der Sīra von Ibn Isḥāq/Ibn Hišām und in Abū ʿUbaids al-Amwāl", "Ein Gedicht von Ḥassān ibn Ṯābit", "Ein Vertrag mit den Persern", "Eine Fatwa des Kalifen ʿUmar"], "Die Ṣaḥīfa ist ein der frühen Zeit in Medina zugeschriebenes Dokument, das die Auswanderer, die Anṣār und die Juden Medinas als Umma hinsichtlich gegenseitiger Verteidigung und Pflichten bestimmt. Sie ist bei Ibn Isḥāq (in Ibn Hišām) ohne vollständige Kette und in Abū ʿUbaids al-Amwāl mit einer Kette überliefert. Moderne Gelehrte bestreiten ihre Datierung und ob es ein oder mehrere Dokumente waren."],
    ar: ["ما «صحيفة المدينة» (التي يسمونها دستور المدينة) وكيف عُرفت؟", ["وثيقة من أوائل العهد المدني تنظم العلاقات بين المهاجرين والأنصار وقبائل اليهود، حُفظت في سيرة ابن إسحاق/ابن هشام وفي «الأموال» لأبي عبيد", "قصيدة لحسان بن ثابت", "معاهدة مع الفرس", "فتوى للخليفة عمر"], "الصحيفة وثيقة تنسب إلى أول العهد المدني تعرّف المهاجرين والأنصار ويهود المدينة أمة في الدفاع المشترك والتبعات، وتُروى عند ابن إسحاق (في ابن هشام) دون إسناد كامل وفي «الأموال» لأبي عبيد بإسناد، ويناقش المحدثون زمنها وهل هي وثيقة واحدة أو عدة وثائق."] },

  { id: "xsr-016", s: "seerah", g: 4, d: 6, t: ["badr", "chronology", "numbers"], src: "Ibn Hishām, al-Sīra; al-Bukhārī, Ṣaḥīḥ, Kitāb al-maghāzī (numbers of Badr); Ibn Saʿd, al-Ṭabaqāt",
    en: ["What do the early sources report as the number of Muslims and of the Quraysh army at Badr?", ["About 313 Muslims (a number in al-Bukhārī, from al-Barā’) against about 950 to 1,000 Quraysh, with few horses on the Muslim side", "About 3,000 Muslims against 300 Quraysh", "About 10,000 Muslims against 100 Quraysh", "About 700 Muslims against 700 Quraysh"], "Al-Bukhārī records from al-Barā’ ibn ʿĀzib that the Companions of Badr numbered a little over three hundred, the number of Ṭālūt’s men. The Quraysh army is reported at about nine hundred and fifty to a thousand. The Muslims had only two or three horses and about seventy camels. Details such as the number of martyrs (fourteen) and of the Quraysh dead (about seventy) are in Ibn Hishām."],
    de: ["Welche Zahl von Muslimen und vom Heer der Quraiš nennen die frühen Quellen für Badr?", ["Etwa 313 Muslime (eine Zahl bei al-Buḫārī, von al-Barāʾ) gegen etwa 950 bis 1000 Quraiš, mit wenigen Pferden auf muslimischer Seite", "Etwa 3000 Muslime gegen 300 Quraiš", "Etwa 10 000 Muslime gegen 100 Quraiš", "Etwa 700 Muslime gegen 700 Quraiš"], "Al-Buḫārī überliefert von al-Barāʾ ibn ʿĀzib, die Gefährten von Badr hätten etwas über dreihundert gezählt, die Zahl der Männer Ṭālūts. Das Heer der Quraiš wird mit etwa neunhundertfünfzig bis tausend angegeben. Die Muslime hatten nur zwei oder drei Pferde und etwa siebzig Kamele. Einzelheiten wie die Zahl der Märtyrer (vierzehn) und der Toten der Quraiš (etwa siebzig) stehen bei Ibn Hišām."],
    ar: ["ما عدد المسلمين وجيش قريش في بدر بحسب المصادر المبكرة؟", ["نحو 313 مسلمًا (عدد ورد في البخاري عن البراء) مقابل نحو 950 إلى ألف من قريش مع قلة الخيل عند المسلمين", "نحو 3000 مسلم مقابل 300 من قريش", "نحو 10000 مسلم مقابل 100 من قريش", "نحو 700 مسلم مقابل 700 من قريش"], "روى البخاري عن البراء بن عازب أن أصحاب بدر كانوا بضعة عشر وثلاثمئة بعدد أصحاب طالوت، وقُدّر جيش قريش بنحو تسعمئة وخمسين إلى ألف، وكان مع المسلمين فرسان أو ثلاثة ونحو سبعين بعيرًا، وفي ابن هشام عدد الشهداء (أربعة عشر) وقتلى قريش (نحو سبعين)."] },

  { id: "xsr-017", s: "seerah", g: 4, d: 7, t: ["badr", "prisoners", "ransom"], src: "Muslim, Ṣaḥīḥ, Kitāb al-jihād (ʿUmar’s report on the prisoners of Badr); Aḥmad, Musnad; Ibn Kathīr, Tafsīr, on sūrat al-Anfāl",
    en: ["What is reported about the dispute over the prisoners of Badr and its link to revelation?", ["The Prophet ﷺ consulted Abū Bakr (who favoured ransom) and ʿUmar (who favoured executing them); ransom was taken, after which verses of sūrat al-Anfāl came down in a tone of reproach, as in ʿUmar’s report in Muslim", "All Companions agreed to free them without ransom", "All Companions agreed to execute them", "The prisoners were sent to Abyssinia"], "ʿUmar’s long report in Ṣaḥīḥ Muslim, from Ibn ʿAbbās, relates that after Badr the Prophet ﷺ asked the opinion of Abū Bakr and ʿUmar about the prisoners. Abū Bakr preferred ransom for the sake of mercy and strength; ʿUmar preferred execution. The Prophet ﷺ took Abū Bakr’s view, and the following day the verses of al-Anfāl reproaching the taking of prisoners before dominance were revealed, as the report states."],
    de: ["Was wird über den Streit um die Gefangenen von Badr und seinen Bezug zur Offenbarung berichtet?", ["Der Prophet ﷺ beriet sich mit Abū Bakr (der für Lösegeld war) und ʿUmar (der für Hinrichtung war); Lösegeld wurde genommen, worauf Verse der Sure al-Anfāl im Ton des Tadels herabkamen, wie in ʿUmars Bericht bei Muslim", "Alle Gefährten waren einig, sie ohne Lösegeld freizulassen", "Alle Gefährten waren einig, sie hinzurichten", "Die Gefangenen wurden nach Abessinien geschickt"], "ʿUmars langer Bericht in Ṣaḥīḥ Muslim von Ibn ʿAbbās erzählt, dass der Prophet ﷺ nach Badr Abū Bakr und ʿUmar zu den Gefangenen befragte. Abū Bakr zog Lösegeld aus Barmherzigkeit und Stärkung vor; ʿUmar die Hinrichtung. Der Prophet ﷺ nahm Abū Bakrs Ansicht an, und am folgenden Tag wurden die Verse von al-Anfāl herabgesandt, die das Nehmen von Gefangenen vor der Vorherrschaft tadeln, wie der Bericht sagt."],
    ar: ["ما المروي عن الخلاف في أسرى بدر وصلته بالوحي؟", ["استشار النبي ﷺ أبا بكر (وقد رأى الفداء) وعمر (وقد رأى القتل) فأخذ الفداء فنزلت آيات من الأنفال تعاتب كما في حديث عمر عند مسلم", "اتفق الصحابة كلهم على إطلاقهم بلا فداء", "اتفق الصحابة كلهم على قتلهم", "أُرسل الأسرى إلى الحبشة"], "يروي حديث عمر الطويل في صحيح مسلم عن ابن عباس أن النبي ﷺ استشار بعد بدر أبا بكر وعمر في الأسرى، فرأى أبو بكر الفداء رحمةً وقوةً ورأى عمر القتل، فأخذ النبي ﷺ برأي أبي بكر، وفي اليوم التالي نزلت آيات الأنفال في عتاب أخذ الأسرى قبل الإثخان كما في الرواية."] },

  { id: "xsr-018", s: "seerah", g: 4, d: 6, t: ["uhud", "archers", "chronology"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-maghāzī (Uḥud, al-Barā’); Ibn Hishām, al-Sīra; Ibn Kathīr, al-Bidāya wa-l-Nihāya",
    en: ["What does the account in al-Bukhārī say about the archers at Uḥud and the reversal of the battle?", ["The Prophet ﷺ stationed fifty archers on the hill under ʿAbd Allāh ibn Jubayr and told them not to leave; most left to collect spoils, and Khālid ibn al-Walīd struck from behind", "The archers were on a ship", "The archers were from Quraysh", "The archers left by the Prophet’s order"], "In the report of al-Barā’ ibn ʿĀzib in al-Bukhārī, the Prophet ﷺ placed archers on the hill, ordered them to stay, even if the Muslims were seen taking the lead or being defeated. When the Quraysh broke, most archers left their position to seek the spoils despite their commander’s warning, and Khālid ibn al-Walīd (then a Qurashī) attacked from the rear. Seventy Muslims were killed."],
    de: ["Was sagt der Bericht bei al-Buḫārī über die Bogenschützen bei Uḥud und die Wende der Schlacht?", ["Der Prophet ﷺ stellte fünfzig Bogenschützen unter ʿAbd Allāh ibn Ǧubair auf den Hügel und befahl, ihn nicht zu verlassen; die meisten gingen weg, um Beute zu sammeln, und Ḫālid ibn al-Walīd griff von hinten an", "Die Bogenschützen waren auf einem Schiff", "Die Bogenschützen gehörten zu Quraiš", "Die Bogenschützen gingen auf Befehl des Propheten"], "Im Bericht von al-Barāʾ ibn ʿĀzib bei al-Buḫārī stellte der Prophet ﷺ Bogenschützen auf den Hügel und befahl ihnen zu bleiben, auch wenn man die Muslime siegen oder besiegt sähe. Als Quraiš zusammenbrach, verließen die meisten Schützen ihre Stellung, um Beute zu suchen, trotz der Warnung ihres Kommandanten, und Ḫālid ibn al-Walīd (damals noch Qurašī) griff von hinten an. Siebzig Muslime wurden getötet."],
    ar: ["ماذا يقول خبر البخاري عن الرماة في أحد وانقلاب المعركة؟", ["أقام النبي ﷺ خمسين رامٍ على الجبل بقيادة عبد الله بن جبير وأمرهم ألا يغادروا، فترك أكثرهم مواقعهم لجمع الغنائم وضربهم خالد بن الوليد من الخلف", "كان الرماة في سفينة", "كان الرماة من قريش", "غادر الرماة بأمر النبي ﷺ"], "في حديث البراء بن عازب في البخاري وضع النبي ﷺ الرماة على الجبل وأمرهم بالبقاء ولو رأوا المسلمين يغلبون أو يُغلبون، فلما انكسرت قريش ترك أكثرهم موقعهم لطلب الغنيمة رغم تحذير أميرهم وكرّ خالد بن الوليد (وكان يومئذ في قريش) من الخلف، واستشهد سبعون من المسلمين."] },

  { id: "xsr-019", s: "seerah", g: 4, d: 7, t: ["khandaq", "ahzab", "banu-qurayza"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-maghāzī (al-Khandaq, Banū Qurayẓa); Ibn Hishām, al-Sīra; Ibn Ḥajar, Fatḥ al-Bārī",
    en: ["What do the early sources say about the Battle of the Trench and the later affair of Banū Qurayẓa?", ["The Muslims dug a trench, following Salmān’s suggestion in the sources; after the Confederates withdrew, the Prophet ﷺ besieged Banū Qurayẓa for breaking the pact, and Saʿd ibn Muʿādh gave the judgement accepted by the Prophet ﷺ", "The trench was dug by the Persians; Banū Qurayẓa were never mentioned", "The Muslims fought in open ground without any trench", "Banū Qurayẓa were allies who joined the Muslims"], "The sources say the Muslims dug a trench around the north of Madīna on the advice of Salmān al-Fārisī, and the Confederates were turned back by siege, wind and dissension. Banū Qurayẓa had been accused of breaking their pact; after a siege they submitted to the judgement of Saʿd ibn Muʿādh, who ruled according to their own law, as in the reports in al-Bukhārī and Muslim. The affair is discussed by later scholars for its details."],
    de: ["Was sagen die frühen Quellen über die Grabenschlacht und die spätere Angelegenheit der Banū Qurayẓa?", ["Die Muslime gruben einen Graben, nach den Quellen auf Salmāns Vorschlag; nach dem Abzug der Verbündeten belagerte der Prophet ﷺ die Banū Qurayẓa wegen Bruchs des Abkommens, und Saʿd ibn Muʿādh sprach das vom Propheten ﷺ angenommene Urteil", "Der Graben wurde von den Persern gegraben; Banū Qurayẓa werden nie erwähnt", "Die Muslime kämpften auf offenem Feld ohne Graben", "Die Banū Qurayẓa waren Verbündete, die sich den Muslimen anschlossen"], "Die Quellen berichten, die Muslime hätten auf Rat Salmān al-Fārisīs einen Graben um den Norden Medinas gegraben, und die Verbündeten seien durch Belagerung, Wind und Zwietracht abgewiesen worden. Den Banū Qurayẓa wurde Bruch ihres Abkommens vorgeworfen; nach einer Belagerung unterwarfen sie sich dem Urteil Saʿd ibn Muʿādhs, der nach ihrem eigenen Recht entschied, wie in den Berichten bei al-Buḫārī und Muslim. Die Angelegenheit wird von späteren Gelehrten wegen ihrer Einzelheiten erörtert."],
    ar: ["ماذا تقول المصادر المبكرة عن غزوة الخندق وما تلاها من شأن بني قريظة؟", ["حفر المسلمون الخندق بمشورة سلمان بحسب المصادر، وبعد انصراف الأحزاب حاصر النبي ﷺ بني قريظة لنقضهم العهد، وحكم فيهم سعد بن معاذ فأمضاه النبي ﷺ", "حفر الخندق الفرس ولم تُذكر بنو قريظة", "قاتل المسلمون في العراء دون خندق", "كانت بنو قريظة حلفاء انضموا إلى المسلمين"], "تذكر المصادر أن المسلمين حفروا خندقًا شمال المدينة بمشورة سلمان الفارسي، وردّ الأحزاب الحصار والريح والفرقة، واتُّهمت بنو قريظة بنقض العهد فحوصروا ونزلوا على حكم سعد بن معاذ فحكم بحسب شريعتهم كما في روايات البخاري ومسلم، وتناول العلماء تفاصيلها بالبحث."] },

  { id: "xsr-020", s: "seerah", g: 4, d: 6, t: ["hudaybiya", "treaty", "terms"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-shurūṭ and Kitāb al-maghāzī; Muslim, Ṣaḥīḥ, Kitāb al-jihād; Ibn Hishām, al-Sīra",
    en: ["Which terms of the Treaty of Ḥudaybiya are named in the sound reports?", ["Ten years of truce, the Muslims to return that year and come for ʿumra the next, return of those who came from Quraysh without permission but not of those who left Muslims, and freedom for tribes to join either side", "Payment of tribute by Quraysh, and the Muslims to remain in Makka", "A union of the two states under one ruler", "Exchange of captives only"], "The reports in al-Bukhārī and Muslim give the terms: a ten-year peace (or two years in some reports), that the Muslims would return without ʿumra that year and come the next, that Quraysh members who came to the Prophet ﷺ without permission would be returned, while those leaving the Muslims would not be returned, and that tribes might ally with either side. Several Companions found the terms hard until the revelation of sūrat al-Fatḥ."],
    de: ["Welche Bedingungen des Vertrags von Ḥudaibiya nennen die gesunden Berichte?", ["Zehn Jahre Waffenruhe, Rückkehr der Muslime in diesem Jahr und ʿUmra im nächsten, Rückgabe derer, die ohne Erlaubnis von Quraiš kamen, aber nicht derer, die die Muslime verließen, und Freiheit der Stämme, sich beiden Seiten anzuschließen", "Tributzahlung der Quraiš und Verbleib der Muslime in Mekka", "Eine Vereinigung beider Staaten unter einem Herrscher", "Nur Gefangenenaustausch"], "Die Berichte bei al-Buḫārī und Muslim nennen die Bedingungen: zehn Jahre Frieden (nach manchen Berichten zwei Jahre), dass die Muslime in diesem Jahr ohne ʿUmra zurückkehren und im nächsten kommen, dass Angehörige der Quraiš, die ohne Erlaubnis zum Propheten ﷺ kamen, zurückgegeben würden, während die, die die Muslime verließen, nicht zurückgegeben würden, und dass Stämme sich beiden Seiten anschließen dürften. Mehrere Gefährten fanden die Bedingungen hart, bis die Sure al-Fatḥ herabkam."],
    ar: ["أي بنود صلح الحديبية تذكرها الروايات الصحيحة؟", ["هدنة عشر سنين، ورجوع المسلمين ذلك العام وعمرتهم القابل، ورد من جاء من قريش بغير إذن وعدم رد من خرج من المسلمين، وحرية القبائل في الدخول في عهد أي الفريقين", "دفع قريش جزية وبقاء المسلمين في مكة", "اتحاد الدولتين تحت حاكم واحد", "تبادل الأسرى فقط"], "تذكر روايات البخاري ومسلم البنود: صلح عشر سنين (وفي بعض الروايات سنتين)، وأن يرجع المسلمون عامهم دون عمرة ويعتمروا من قابل، وأن يُرد من جاء من قريش للنبي ﷺ بغير إذن وليّه ولا يُرد من خرج من المسلمين إلى قريش، وأن للقبائل أن تدخل في عهد أيهما، وشقّت الشروط على بعض الصحابة حتى نزلت سورة الفتح."] },

  { id: "xsr-021", s: "seerah", g: 4, d: 7, t: ["letters", "kings", "heraclius"], src: "al-Bukhārī, Ṣaḥīḥ, Bad’ al-waḥy (Heraclius and Abū Sufyān); Muslim, Ṣaḥīḥ, Kitāb al-jihād; Ibn Saʿd, al-Ṭabaqāt; Muḥammad Ḥamīdullāh, Majmūʿat al-Wathāʾiq al-Siyāsiyya",
    en: ["What is the best-attested exchange of the Prophet’s letters to rulers in the sound sources?", ["The letter to Heraclius, carried by Diḥya al-Kalbī, and the questions Heraclius put to Abū Sufyān, reported in al-Bukhārī from Ibn ʿAbbās", "The letter to the Chinese emperor, reported in Muslim", "The letter to the Pope, reported in Abū Dāwūd", "The letter to the king of India, reported in al-Tirmidhī"], "Al-Bukhārī opens his book with the account of Heraclius, who summoned Abū Sufyān and asked about the Prophet’s lineage, followers and conduct after receiving the Prophet’s letter, carried by Diḥya al-Kalbī. Letters to the Negus, Khosrow and the Muqawqis are also reported in the sources, although the texts of some come with differing chains and the authenticity of certain versions is debated among historians."],
    de: ["Welcher Briefwechsel des Propheten mit Herrschern ist in den gesunden Quellen am besten belegt?", ["Der Brief an Herakleios, überbracht von Diḥya al-Kalbī, und die Fragen, die Herakleios Abū Sufyān stellte, bei al-Buḫārī von Ibn ʿAbbās überliefert", "Der Brief an den chinesischen Kaiser, bei Muslim überliefert", "Der Brief an den Papst, bei Abū Dāwūd überliefert", "Der Brief an den König von Indien, bei at-Tirmiḏī überliefert"], "Al-Buḫārī eröffnet sein Buch mit dem Bericht über Herakleios, der Abū Sufyān rief und nach Abstammung, Anhängern und Verhalten des Propheten fragte, nachdem er dessen Brief erhalten hatte, den Diḥya al-Kalbī überbrachte. Briefe an den Negus, Chosrau und den Muqauqis werden ebenfalls in den Quellen berichtet, wobei die Texte einiger mit unterschiedlichen Ketten kommen und die Echtheit mancher Fassungen unter Historikern umstritten ist."],
    ar: ["ما أصح ما ثبت في المصادر الصحيحة من مراسلات النبي ﷺ للملوك؟", ["كتابه إلى هرقل مع دحية الكلبي وأسئلة هرقل لأبي سفيان في البخاري عن ابن عباس", "كتابه إلى إمبراطور الصين في مسلم", "كتابه إلى البابا في أبي داود", "كتابه إلى ملك الهند في الترمذي"], "افتتح البخاري كتابه بقصة هرقل الذي استدعى أبا سفيان وسأله عن نسب النبي ﷺ وأتباعه وسلوكه بعد أن وصله كتابه مع دحية الكلبي، وتُروى كتب إلى النجاشي وكسرى والمقوقس أيضًا، لكن بعض نصوصها جاء بأسانيد متفاوتة ويختلف المؤرخون في صحة بعض صيغها."] },

  { id: "xsr-022", s: "seerah", g: 4, d: 6, t: ["mecca-conquest", "amnesty", "chronology"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-maghāzī (fatḥ Makka); Muslim, Ṣaḥīḥ; Ibn Hishām, al-Sīra",
    en: ["What do the sound reports record about the entry into Makka in 8 AH?", ["The Prophet ﷺ entered with a large army without major fighting, proclaimed security for those who stayed in their houses, in the Kaʿba or in the house of Abū Sufyān, and cleansed the Kaʿba of idols", "He entered alone at night and left the same day", "He destroyed Makka and took its people as captives", "He entered by ship"], "The reports (al-Bukhārī, Muslim) tell that after Quraysh’s breach of the Ḥudaybiya terms, the Prophet ﷺ marched in the month of Ramadan with about ten thousand men. Abū Sufyān embraced Islam before the entry, and there was security for those in his house. The Prophet ﷺ entered the sanctuary, circled the Kaʿba and had the idols removed. A few individuals were excepted from the amnesty according to the sources."],
    de: ["Was verzeichnen die gesunden Berichte über den Einzug in Mekka im Jahr 8 n. H.?", ["Der Prophet ﷺ zog mit einem großen Heer ohne größere Kämpfe ein, verkündete Sicherheit für die, die in ihren Häusern, in der Kaaba oder im Haus Abū Sufyāns blieben, und reinigte die Kaaba von Götzenbildern", "Er zog allein bei Nacht ein und verließ die Stadt am selben Tag", "Er zerstörte Mekka und nahm seine Leute gefangen", "Er zog mit dem Schiff ein"], "Die Berichte (al-Buḫārī, Muslim) erzählen, dass der Prophet ﷺ nach dem Bruch der Ḥudaibiya-Bedingungen durch Quraiš im Monat Ramadan mit etwa zehntausend Mann zog. Abū Sufyān nahm vor dem Einzug den Islam an, und wer in seinem Haus war, hatte Sicherheit. Der Prophet ﷺ betrat das Heiligtum, umschritt die Kaaba und ließ die Götzenbilder entfernen. Einige wenige Personen wurden nach den Quellen von der Amnestie ausgenommen."],
    ar: ["ماذا تسجل الروايات الصحيحة عن دخول مكة سنة 8هـ؟", ["دخلها النبي ﷺ بجيش كبير دون قتال يُذكر وأعلن الأمان لمن بقي في بيته أو في الكعبة أو في دار أبي سفيان وطهّر الكعبة من الأصنام", "دخلها وحده ليلًا وغادرها في اليوم نفسه", "خرّب مكة وسبى أهلها", "دخلها بحرًا"], "تروي الصحاح (البخاري ومسلم) أن النبي ﷺ سار في رمضان بنحو عشرة آلاف بعد نقض قريش شروط الحديبية، وأسلم أبو سفيان قبل الدخول وأُعلن الأمان لمن في داره، ودخل النبي ﷺ الحرم وطاف بالكعبة وأزال الأصنام، واستُثني من الأمان نفر قليل بحسب المصادر."] },

  { id: "xsr-023", s: "seerah", g: 4, d: 7, t: ["hunayn", "taif-siege", "spoils"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-maghāzī (Ḥunayn, al-Barā’); Muslim, Ṣaḥīḥ; Ibn Hishām, al-Sīra",
    en: ["What do the sound reports record about the Battle of Ḥunayn and the distribution that followed?", ["The Muslims at first fell back under the ambush of Hawāzin, then rallied around the Prophet ﷺ; afterwards he gave generously to recent converts (al-muʾallafa qulūbuhum), which led to complaints among some Anṣār", "The Muslims won without any difficulty", "The Muslims were defeated and returned to Madīna", "No spoils were distributed"], "In al-Barā’’s report in al-Bukhārī, the Muslims were surprised by Hawāzin’s archers in the valley and many scattered, while the Prophet ﷺ held his ground and called to be rallied. After the victory, spoils were distributed with large shares to new Muslims from Quraysh and others, and some of the Anṣār voiced displeasure, to which the Prophet ﷺ replied with an address (reported in the Ṣaḥīḥayn) reminding them that they returned with the Messenger of God."],
    de: ["Was verzeichnen die gesunden Berichte über die Schlacht von Ḥunain und die anschließende Verteilung?", ["Die Muslime wichen zunächst unter dem Hinterhalt der Hawāzin zurück, sammelten sich dann um den Propheten ﷺ; danach gab er großzügig an Neubekehrte (al-muʾallafa qulūbuhum), was bei manchen Anṣār zu Klagen führte", "Die Muslime siegten ohne Schwierigkeit", "Die Muslime wurden besiegt und kehrten nach Medina zurück", "Es wurde keine Beute verteilt"], "Im Bericht al-Barāʾs bei al-Buḫārī wurden die Muslime im Tal von den Bogenschützen der Hawāzin überrascht, und viele zerstreuten sich, während der Prophet ﷺ standhielt und zum Sammeln rief. Nach dem Sieg wurde Beute verteilt, mit großen Anteilen an neue Muslime aus Quraiš und anderen, und einige Anṣār äußerten Unmut, worauf der Prophet ﷺ mit einer Ansprache antwortete (in den Ṣaḥīḥain berichtet), die sie erinnerte, dass sie mit dem Gesandten Gottes heimkehrten."],
    ar: ["ماذا تسجل الروايات الصحيحة عن غزوة حنين وما تلاها من القسمة؟", ["تراجع المسلمون أولًا تحت كمين هوازن ثم ثابوا حول النبي ﷺ، وبعد ذلك أعطى المؤلفة قلوبهم عطاء كبيرًا فتكلم بعض الأنصار", "انتصر المسلمون دون أي مشقة", "هُزم المسلمون وعادوا إلى المدينة", "لم تُوزع غنائم"], "في حديث البراء في البخاري باغتت رماة هوازن المسلمين في الوادي فتفرق كثير منهم وثبت النبي ﷺ ينادي، وبعد النصر قسّمت الغنائم وأُعطي حديثو الإسلام من قريش وغيرهم أنصبة كبيرة فتكلم بعض الأنصار، فخطبهم النبي ﷺ (في الصحيحين) مذكرًا أنهم يرجعون برسول الله ﷺ."] },

  { id: "xsr-024", s: "seerah", g: 4, d: 6, t: ["tabuk", "kab-ibn-malik", "three-who-stayed"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-maghāzī (Kaʿb ibn Mālik’s account); Muslim, Ṣaḥīḥ, Kitāb al-tawba; Ibn Hishām, al-Sīra",
    en: ["Which sound report relates the expedition to Tabūk and the three Companions who stayed behind?", ["The long first-person account of Kaʿb ibn Mālik in al-Bukhārī and Muslim, about the boycott of him, Hilāl ibn Umayya and Murāra ibn al-Rabīʿ and their forgiveness", "The account of Abū Hurayra on the conquest of Egypt", "The account of ʿĀʾisha on the Battle of the Camel", "The account of Anas on the Battle of Yarmūk"], "Kaʿb ibn Mālik himself told how he stayed behind from the Tabūk expedition (9 AH) without excuse, was boycotted for fifty days with two others, and was finally forgiven by a verse of sūrat al-Tawba. The account is one of the longest in al-Bukhārī and Muslim and is widely used for lessons on truthfulness."],
    de: ["Welcher gesunde Bericht erzählt vom Feldzug nach Tabūk und den drei Gefährten, die zurückblieben?", ["Der lange Ich-Bericht Kaʿb ibn Māliks bei al-Buḫārī und Muslim über den Boykott gegen ihn, Hilāl ibn Umayya und Murāra ibn ar-Rabīʿ und ihre Vergebung", "Der Bericht Abū Hurairas über die Eroberung Ägyptens", "Der Bericht ʿĀʾišas über die Kamelschlacht", "Der Bericht des Anas über die Schlacht am Yarmūk"], "Kaʿb ibn Mālik selbst erzählte, wie er vom Feldzug nach Tabūk (9 n. H.) ohne Entschuldigung zurückblieb, mit zwei anderen fünfzig Tage lang boykottiert und schließlich durch einen Vers der Sure at-Tauba begnadigt wurde. Der Bericht gehört zu den längsten bei al-Buḫārī und Muslim und wird weithin für Lehren über Wahrhaftigkeit gebraucht."],
    ar: ["أي رواية صحيحة تروي غزوة تبوك والثلاثة الذين خُلّفوا؟", ["حديث كعب بن مالك الطويل بلسانه في البخاري ومسلم عن مقاطعته مع هلال بن أمية ومرارة بن الربيع وقبول توبتهم", "حديث أبي هريرة عن فتح مصر", "حديث عائشة عن وقعة الجمل", "حديث أنس عن معركة اليرموك"], "روى كعب بن مالك بنفسه كيف تخلف عن غزوة تبوك (9هـ) بلا عذر وهُجر خمسين يومًا مع صاحبيه ثم تاب الله عليهم بآية في سورة التوبة، وحديثه من أطول الأحاديث في البخاري ومسلم ويُستدل به كثيرًا في الصدق."] },

  { id: "xsr-025", s: "seerah", g: 4, d: 7, t: ["farewell-hajj", "chronology", "year-10"], src: "Muslim, Ṣaḥīḥ, Kitāb al-ḥajj (Jābir’s long ḥadīth); al-Bukhārī, Ṣaḥīḥ; Ibn Hishām, al-Sīra",
    en: ["What is the main source for the details of the Farewell Pilgrimage, and what disagreement exists about the manner of ihrām?", ["Jābir’s long ḥadīth in Muslim; scholars differ whether the Prophet ﷺ performed ifrād, qirān or tamattuʿ, with each position having supporters, and the Ḥanafīs favouring qirān", "Anas’s ḥadīth on the Night Journey; all agree on tamattuʿ", "ʿUmar’s ḥadīth on Ḥudaybiya; all agree on ifrād", "The Quran alone; there is no hadith"], "Jābir ibn ʿAbd Allāh’s account in Muslim describes the ḥajj step by step, in the tenth year. The reports about what ihrām the Prophet ﷺ made differ: some say ifrād, some qirān, some tamattuʿ, and each school reconciled them in its own way. The Ḥanafīs held qirān to be the best, the Shāfiʿīs ifrād, and the Ḥanbalīs generally tamattuʿ."],
    de: ["Was ist die Hauptquelle für die Einzelheiten der Abschiedspilgerfahrt, und welche Meinungsverschiedenheit besteht über die Art des Iḥrām?", ["Ǧābirs langer Hadith bei Muslim; die Gelehrten sind uneins, ob der Prophet ﷺ Ifrād, Qirān oder Tamattuʿ vollzog, wobei jede Position Anhänger hat und die Ḥanafiten Qirān bevorzugen", "Anas’ Hadith über die Nachtreise; alle sind sich über Tamattuʿ einig", "ʿUmars Hadith über Ḥudaibiya; alle sind sich über Ifrād einig", "Der Koran allein; es gibt keinen Hadith"], "Ǧābir ibn ʿAbd Allāhs Bericht bei Muslim beschreibt den Ḥaǧǧ im zehnten Jahr Schritt für Schritt. Die Berichte darüber, welchen Iḥrām der Prophet ﷺ anlegte, unterscheiden sich: manche sagen Ifrād, manche Qirān, manche Tamattuʿ, und jede Schule vereinbarte sie auf ihre Weise. Die Ḥanafiten hielten Qirān für das Beste, die Šāfiʿiten Ifrād und die Ḥanbaliten im Allgemeinen Tamattuʿ."],
    ar: ["ما المصدر الرئيس لتفاصيل حجة الوداع وما الخلاف في كيفية إحرامه ﷺ؟", ["حديث جابر الطويل في مسلم، ويختلف العلماء هل كان إفرادًا أو قرانًا أو تمتعًا ولكل قول أنصار والحنفية يفضلون القران", "حديث أنس عن الإسراء، والكل متفق على التمتع", "حديث عمر عن الحديبية، والكل متفق على الإفراد", "القرآن وحده ولا حديث"], "يصف حديث جابر بن عبد الله في مسلم الحج خطوة خطوة في السنة العاشرة، وتختلف الروايات في نوع إحرامه ﷺ فقيل إفراد وقيل قران وقيل تمتع، وجمعت كل مذهب بينها بطريقته، فالحنفية يرون القران أفضل والشافعية الإفراد والحنابلة عمومًا التمتع."] },

  { id: "xsr-026", s: "seerah", g: 4, d: 7, t: ["death", "succession", "saqifa"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb faḍāʾil aṣḥāb al-nabī and Kitāb al-ḥudūd (ʿUmar’s khuṭba); Ibn Hishām, al-Sīra; al-Ṭabarī, Taʾrīkh",
    en: ["What do the sound reports say about the aftermath of the Prophet’s death and the Saqīfa of Banū Sāʿida?", ["ʿUmar at first denied the death, Abū Bakr recited the verse that Muḥammad is only a messenger, and at the Saqīfa the Anṣār and Emigrants debated; ʿUmar pledged to Abū Bakr and others followed", "The Anṣār chose ʿAlī immediately without debate", "The Prophet ﷺ named his successor in a written will accepted by all", "The matter was settled by Quraysh in Makka"], "In al-Bukhārī’s reports, ʿUmar refused to believe the Prophet ﷺ had died until Abū Bakr arrived, praised God, and recited the verse that Muḥammad is but a messenger. At the Saqīfa, the Anṣār gathered around Saʿd ibn ʿUbāda; Abū Bakr, ʿUmar and Abū ʿUbayda joined, and after discussion ʿUmar pledged to Abū Bakr, followed by others. ʿUmar’s later khuṭba described the pledge as a sudden event (falta) from which God protected the community."],
    de: ["Was sagen die gesunden Berichte über die Folgen des Todes des Propheten und die Saqīfa der Banū Sāʿida?", ["ʿUmar leugnete zunächst den Tod, Abū Bakr rezitierte den Vers, dass Muḥammad nur ein Gesandter ist, und in der Saqīfa debattierten Anṣār und Auswanderer; ʿUmar schwor Abū Bakr den Treueid und andere folgten", "Die Anṣār wählten sofort ʿAlī ohne Debatte", "Der Prophet ﷺ benannte seinen Nachfolger in einem schriftlichen Testament, das alle annahmen", "Die Angelegenheit wurde von Quraiš in Mekka entschieden"], "In al-Buḫārīs Berichten weigerte sich ʿUmar zu glauben, dass der Prophet ﷺ gestorben war, bis Abū Bakr kam, Gott pries und den Vers rezitierte, dass Muḥammad nur ein Gesandter ist. In der Saqīfa versammelten sich die Anṣār um Saʿd ibn ʿUbāda; Abū Bakr, ʿUmar und Abū ʿUbaida kamen hinzu, und nach Erörterung schwor ʿUmar Abū Bakr den Treueid, dann andere. ʿUmars spätere Predigt beschrieb den Treueid als plötzliches Ereignis (falta), vor dessen Übel Gott die Gemeinschaft bewahrte."],
    ar: ["ماذا تقول الروايات الصحيحة عما جرى بعد وفاة النبي ﷺ وفي سقيفة بني ساعدة؟", ["أنكر عمر الوفاة أولًا وتلا أبو بكر الآية أن محمدًا إلا رسول، وتناظر الأنصار والمهاجرون في السقيفة فبايع عمر أبا بكر وتبعه الناس", "اختار الأنصار عليًّا فورًا دون نقاش", "عيّن النبي ﷺ خليفته في وصية مكتوبة قبلها الجميع", "حُسم الأمر بين قريش في مكة"], "في روايات البخاري رفض عمر تصديق وفاة النبي ﷺ حتى جاء أبو بكر فحمد الله وتلا الآية أن محمدًا إلا رسول، وفي السقيفة اجتمع الأنصار حول سعد بن عبادة وحضر أبو بكر وعمر وأبو عبيدة، وبعد النقاش بايع عمر أبا بكر ثم الناس، ووصف عمر في خطبة لاحقة البيعة بأنها فلتة وقى الله شرها."] },

  { id: "xsr-027", s: "seerah", g: 4, d: 6, t: ["wives", "mothers-of-believers", "marriages"], src: "Ibn Saʿd, al-Ṭabaqāt al-Kubrā; Ibn Kathīr, al-Bidāya wa-l-Nihāya; al-Nawawī, Tahdhīb al-Asmāʾ wa-l-Lughāt",
    en: ["What is the order and the number of the Prophet’s wives who survived him or were married during his life, according to the common account?", ["Eleven wives are commonly counted in his life with Khadīja and Zaynab bint Khuzayma having died before him, and nine survived him; the first marriage was to Khadīja", "He had a single wife throughout his life", "He had twenty wives who all survived him", "The sources give no information"], "The common account is that his first wife was Khadīja, followed (after her death) by Sawda, ʿĀʾisha, Ḥafṣa, Zaynab bint Khuzayma (who died soon), Umm Salama, Zaynab bint Jaḥsh, Juwayriya, Umm Ḥabība, Ṣafiyya and Maymūna. Nine wives survived him. The accounts also mention Māriya al-Qibṭiyya, whose status is discussed as a concubine. The ‘Mothers of the Believers’ is the title given to the wives in sūrat al-Aḥzāb."],
    de: ["Wie lautet nach dem üblichen Bericht die Zahl der Frauen des Propheten, die er in seinem Leben heiratete bzw. die ihn überlebten?", ["Elf Frauen werden in seinem Leben üblicherweise gezählt, wobei Ḫadīǧa und Zainab bint Ḫuzaima vor ihm starben und neun ihn überlebten; die erste Ehe war mit Ḫadīǧa", "Er hatte sein ganzes Leben nur eine Frau", "Er hatte zwanzig Frauen, die alle ihn überlebten", "Die Quellen geben keine Auskunft"], "Der übliche Bericht lautet, dass seine erste Frau Ḫadīǧa war, gefolgt (nach ihrem Tod) von Sauda, ʿĀʾiša, Ḥafṣa, Zainab bint Ḫuzaima (die bald starb), Umm Salama, Zainab bint Ǧaḥš, Ǧuwairiya, Umm Ḥabība, Ṣafiyya und Maimūna. Neun Frauen überlebten ihn. Die Berichte erwähnen auch Māriya al-Qibṭiyya, deren Status als Konkubine erörtert wird. ‚Mütter der Gläubigen‘ ist der Titel, der den Frauen in der Sure al-Aḥzāb gegeben wird."],
    ar: ["ما عدد أزواج النبي ﷺ وترتيبهن بحسب الرواية الشائعة ومن بقي منهن بعده؟", ["يُعد له أحد عشر زوجة في حياته ماتت خديجة وزينب بنت خزيمة قبله وبقيت تسع بعده، وأولهن خديجة", "كانت له زوجة واحدة طوال حياته", "كان له عشرون زوجة بقين كلهن بعده", "لا تذكر المصادر شيئًا"], "الرواية الشائعة أن أولى زوجاته خديجة ثم (بعد وفاتها) سودة وعائشة وحفصة وزينب بنت خزيمة (وتوفيت قريبًا) وأم سلمة وزينب بنت جحش وجويرية وأم حبيبة وصفية وميمونة، وبقيت تسع بعده، وتذكر المصادر مارية القبطية ويناقش وضعها سرية، و«أمهات المؤمنين» لقب أزواجه في سورة الأحزاب."] },

  { id: "xsr-028", s: "seerah", g: 4, d: 7, t: ["children", "ibrahim", "fatima"], src: "Ibn Saʿd, al-Ṭabaqāt al-Kubrā; Ibn Hishām, al-Sīra; Ibn Kathīr, al-Bidāya wa-l-Nihāya; al-Bukhārī, Ṣaḥīḥ (death of Ibrāhīm and the eclipse)",
    en: ["What do the sources say about the Prophet’s children and the death of Ibrāhīm?", ["From Khadīja came al-Qāsim, Zaynab, Ruqayya, Umm Kulthūm, Fāṭima and ʿAbd Allāh; Ibrāhīm was born to Māriya and died in infancy, the day of an eclipse mentioned in a report, to which the Prophet ﷺ said that eclipses are not caused by anyone’s death", "He had twelve sons who survived him", "He had no children at all", "His only child was Fāṭima"], "The sources agree that all children except Ibrāhīm were from Khadīja; the sons died young, and all daughters except Fāṭima died during his life. Ibrāhīm, son of Māriya al-Qibṭiyya, died aged about a year and a half. Al-Bukhārī relates that a solar eclipse occurred on that day and people linked it to the death, and the Prophet ﷺ stated that the sun and moon are signs of God, and do not eclipse for anyone’s death or life."],
    de: ["Was sagen die Quellen über die Kinder des Propheten und den Tod Ibrāhīms?", ["Von Ḫadīǧa stammten al-Qāsim, Zainab, Ruqayya, Umm Kulṯūm, Fāṭima und ʿAbd Allāh; Ibrāhīm wurde von Māriya geboren und starb als Kleinkind am Tag einer in einem Bericht erwähnten Finsternis, worauf der Prophet ﷺ sagte, Finsternisse würden nicht durch den Tod von jemandem verursacht", "Er hatte zwölf Söhne, die ihn überlebten", "Er hatte überhaupt keine Kinder", "Sein einziges Kind war Fāṭima"], "Die Quellen stimmen überein, dass alle Kinder außer Ibrāhīm von Ḫadīǧa waren; die Söhne starben jung, und alle Töchter außer Fāṭima starben zu seinen Lebzeiten. Ibrāhīm, Sohn der Māriya al-Qibṭiyya, starb im Alter von etwa anderthalb Jahren. Al-Buḫārī überliefert, dass an jenem Tag eine Sonnenfinsternis auftrat und die Leute sie mit dem Tod verbanden, und der Prophet ﷺ erklärte, Sonne und Mond seien Zeichen Gottes und verfinsterten sich nicht wegen des Todes oder Lebens von jemandem."],
    ar: ["ماذا تقول المصادر عن أولاد النبي ﷺ ووفاة إبراهيم؟", ["من خديجة القاسم وزينب ورقية وأم كلثوم وفاطمة وعبد الله، وولد إبراهيم من مارية ومات رضيعًا يوم كسوف ذكرته رواية وقال النبي ﷺ إن الكسوف لا يكون لموت أحد", "كان له اثنا عشر ابنًا بقوا بعده", "لم يكن له أولاد", "كان ولده الوحيد فاطمة"], "اتفقت المصادر على أن أولاده كلهم من خديجة إلا إبراهيم، وماتت بناته في حياته إلا فاطمة وماتت الذكور صغارًا، وإبراهيم ابن مارية القبطية مات وله نحو سنة ونصف، وروى البخاري أن الشمس انكسفت يوم موته فقال الناس انكسفت لموته، فقال النبي ﷺ إن الشمس والقمر آيتان من آيات الله لا ينكسفان لموت أحد ولا لحياته."] },

  { id: "xsr-029", s: "seerah", g: 4, d: 6, t: ["companions", "ten-promised", "ashara-mubashshara"], tr: ["sunni"], src: "al-Tirmidhī, Jāmiʿ, Kitāb al-manāqib (ḥadīth Saʿīd ibn Zayd); Abū Dāwūd, Sunan; Ibn Mājah, Sunan",
    en: ["Who are the ten promised Paradise (al-ʿashara al-mubashshara) according to the report transmitted in the Sunan?", ["Abū Bakr, ʿUmar, ʿUthmān, ʿAlī, Ṭalḥa, al-Zubayr, ʿAbd al-Raḥmān ibn ʿAwf, Saʿd ibn Abī Waqqāṣ, Saʿīd ibn Zayd and Abū ʿUbayda ibn al-Jarrāḥ", "Only the first four caliphs", "Khālid ibn al-Walīd and Bilāl", "Ten women of the Anṣār"], "A report in Abū Dāwūd, al-Tirmidhī and Ibn Mājah, from Saʿīd ibn Zayd, names the ten Companions given good news of Paradise by the Prophet ﷺ in one sitting. The report is judged ṣaḥīḥ by several scholars, though some scholars discussed variants of its chain. The promise to others is also found in separate reports, so the ten are not the only ones promised."],
    de: ["Wer sind die zehn, denen das Paradies verheißen wurde (al-ʿašara al-mubašschara), nach dem in den Sunan überlieferten Bericht?", ["Abū Bakr, ʿUmar, ʿUṯmān, ʿAlī, Ṭalḥa, az-Zubair, ʿAbd ar-Raḥmān ibn ʿAuf, Saʿd ibn Abī Waqqāṣ, Saʿīd ibn Zaid und Abū ʿUbaida ibn al-Ǧarrāḥ", "Nur die ersten vier Kalifen", "Ḫālid ibn al-Walīd und Bilāl", "Zehn Frauen der Anṣār"], "Ein Bericht bei Abū Dāwūd, at-Tirmiḏī und Ibn Māǧa von Saʿīd ibn Zaid nennt die zehn Gefährten, denen der Prophet ﷺ in einer Sitzung die frohe Botschaft des Paradieses gab. Der Bericht wird von mehreren Gelehrten als ṣaḥīḥ beurteilt, obwohl einige Varianten seiner Kette erörterten. Die Verheißung an andere findet sich auch in gesonderten Berichten, sodass die zehn nicht die einzigen Verheißenen sind."],
    ar: ["من العشرة المبشرون بالجنة بحسب الحديث المروي في السنن؟", ["أبو بكر وعمر وعثمان وعلي وطلحة والزبير وعبد الرحمن بن عوف وسعد بن أبي وقاص وسعيد بن زيد وأبو عبيدة بن الجراح", "الخلفاء الأربعة فقط", "خالد بن الوليد وبلال", "عشر نساء من الأنصار"], "يسمي حديث سعيد بن زيد عند أبي داود والترمذي وابن ماجه العشرة الذين بشرهم النبي ﷺ بالجنة في مجلس واحد، وصححه عدد من العلماء مع نقاش في بعض وجوه إسناده، وثبتت البشارة لغيرهم أيضًا في أحاديث أخرى فليس العشرة وحدهم."] },

  { id: "xsr-030", s: "seerah", g: 4, d: 7, t: ["companions", "ahl-badr", "ahl-suffa"], src: "Abū Nuʿaym, Ḥilyat al-Awliyāʾ (Ahl al-Ṣuffa); Ibn Saʿd, al-Ṭabaqāt; Ibn Ḥajar, al-Iṣāba; al-Bukhārī, Ṣaḥīḥ (Ḥāṭib ibn Abī Baltaʿa)",
    en: ["Who were the Ahl al-Ṣuffa, and what is the status of the people of Badr in the reports?", ["The poor Emigrants who lodged in a covered area of the Prophet’s mosque and relied on charity; the Prophet ﷺ said that God may have looked at the people of Badr and forgiven them, as in the report on Ḥāṭib ibn Abī Baltaʿa", "A band of poets who recited in the mosque", "A group of traders from Syria", "The guards of the Kaʿba"], "Ahl al-Ṣuffa were poor Muslims with no home, including Abū Hurayra, who stayed near the Prophet ﷺ in a shaded part of the mosque. The people of Badr hold a special status in the Sunna: in al-Bukhārī’s report on Ḥāṭib, who had written to Quraysh, the Prophet ﷺ declined ʿUmar’s request to execute him by saying that he had been at Badr and God may have looked on the Badr fighters, saying to do what they wish, for they were forgiven."],
    de: ["Wer waren die Ahl aṣ-Ṣuffa, und welchen Status haben die Leute von Badr in den Berichten?", ["Die armen Auswanderer, die in einem überdachten Bereich der Moschee des Propheten wohnten und von Almosen lebten; der Prophet ﷺ sagte, Gott habe vielleicht auf die Leute von Badr geblickt und ihnen vergeben, wie im Bericht über Ḥāṭib ibn Abī Baltaʿa", "Eine Gruppe von Dichtern, die in der Moschee rezitierten", "Eine Gruppe syrischer Händler", "Die Wächter der Kaaba"], "Die Ahl aṣ-Ṣuffa waren arme Muslime ohne Heim, darunter Abū Huraira, die in einem überdachten Teil der Moschee in der Nähe des Propheten ﷺ blieben. Die Leute von Badr haben in der Sunna einen besonderen Status: Im Bericht bei al-Buḫārī über Ḥāṭib, der an Quraiš geschrieben hatte, lehnte der Prophet ﷺ ʿUmars Bitte um dessen Hinrichtung ab, indem er sagte, er sei bei Badr gewesen und Gott habe vielleicht auf die Kämpfer von Badr geblickt und gesagt, sie sollten tun, was sie wollen, denn ihnen sei vergeben."],
    ar: ["من أهل الصفة وما منزلة أهل بدر في الروايات؟", ["فقراء المهاجرين الذين أووا إلى مكان مظلل في مسجد النبي ﷺ وعاشوا على الصدقة، وقال النبي ﷺ إن الله اطلع على أهل بدر فغفر لهم كما في خبر حاطب بن أبي بلتعة", "فرقة من الشعراء كانوا ينشدون في المسجد", "جماعة من تجار الشام", "حراس الكعبة"], "أهل الصفة فقراء المسلمين الذين لا مأوى لهم ومنهم أبو هريرة وقد أقاموا في ظلة من المسجد قرب النبي ﷺ، ولأهل بدر مكانة خاصة في السنة: ففي خبر حاطب في البخاري الذي كتب إلى قريش رد النبي ﷺ طلب عمر بقتله وقال إنه شهد بدرًا وما يدريك لعل الله اطلع على أهل بدر فقال اعملوا ما شئتم فقد غفرت لكم."] },

  { id: "xsr-031", s: "seerah", g: 4, d: 6, t: ["shamail", "description", "sources"], src: "al-Tirmidhī, al-Shamāʾil al-Muḥammadiyya; al-Bukhārī, Ṣaḥīḥ (Kitāb al-manāqib); Muslim, Ṣaḥīḥ (Kitāb al-faḍāʾil); al-Qāḍī ʿIyāḍ, al-Shifā bi-Taʿrīf Ḥuqūq al-Muṣṭafā",
    en: ["Which classical works are the principal collections on the Prophet’s description and character?", ["al-Tirmidhī’s al-Shamāʾil al-Muḥammadiyya and al-Qāḍī ʿIyāḍ’s al-Shifā bi-Taʿrīf Ḥuqūq al-Muṣṭafā", "al-Ghazālī’s al-Mustaṣfā", "Sībawayh’s al-Kitāb", "al-Shāṭibī’s al-Muwāfaqāt"], "Al-Tirmidhī’s al-Shamāʾil collects hadith on the Prophet’s appearance, dress, food, walk and manners. Al-Qāḍī ʿIyāḍ’s al-Shifā (d. 544 AH) treats his rights and virtues and includes description. The other works named belong to uṣūl al-fiqh and Arabic grammar. Both principal works were extensively commented upon, for example the Shamāʾil by al-Bājūrī."],
    de: ["Welche klassischen Werke sind die wichtigsten Sammlungen über Beschreibung und Charakter des Propheten?", ["At-Tirmiḏīs aš-Šamāʾil al-Muḥammadiyya und al-Qāḍī ʿIyāḍs aš-Šifā bi-Taʿrīf Ḥuqūq al-Muṣṭafā", "Al-Ġazālīs al-Mustaṣfā", "Sībawaihs al-Kitāb", "Aš-Šāṭibīs al-Muwāfaqāt"], "At-Tirmiḏīs aš-Šamāʾil sammelt Hadithe über Aussehen, Kleidung, Speise, Gang und Umgangsformen des Propheten. Al-Qāḍī ʿIyāḍs aš-Šifā (gest. 544 n. H.) behandelt seine Rechte und Vorzüge und enthält Beschreibung. Die anderen genannten Werke gehören zur Uṣūl al-Fiqh und zur arabischen Grammatik. Beide Hauptwerke wurden ausführlich kommentiert, etwa die Šamāʾil von al-Bāǧūrī."],
    ar: ["أي الكتب الكلاسيكية أهم ما جُمع في وصف النبي ﷺ وأخلاقه؟", ["«الشمائل المحمدية» للترمذي و«الشفا بتعريف حقوق المصطفى» للقاضي عياض", "«المستصفى» للغزالي", "«الكتاب» لسيبويه", "«الموافقات» للشاطبي"], "يجمع كتاب «الشمائل» للترمذي أحاديث هيئة النبي ﷺ ولباسه وطعامه ومشيته وآدابه، ويعالج «الشفا» للقاضي عياض (ت 544هـ) حقوقه وفضائله ويتضمن الوصف، والكتب الأخرى في أصول الفقه والنحو، وشُرح الكتابان شروحًا كثيرة كشرح الباجوري للشمائل."] },

  { id: "xsr-032", s: "seerah", g: 4, d: 7, t: ["dalail-nubuwwa", "miracles", "works"], src: "al-Bayhaqī, Dalāʾil al-Nubuwwa; Abū Nuʿaym, Dalāʾil al-Nubuwwa; al-Māwardī, Aʿlām al-Nubuwwa; Ibn Kathīr, al-Bidāya wa-l-Nihāya",
    en: ["Which authors wrote the best-known works titled 'Dalāʾil al-Nubuwwa' (Proofs of Prophethood)?", ["Abū Nuʿaym al-Iṣbahānī (d. 430 AH) and al-Bayhaqī (d. 458 AH), the latter being the most comprehensive and drawing on early maghāzī", "al-Bukhārī and Muslim", "Ibn Hishām and al-Wāqidī", "Ibn Mālik and Sībawayh"], "Abū Nuʿaym’s Dalāʾil al-Nubuwwa and al-Bayhaqī’s Dalāʾil al-Nubuwwa wa-Maʿrifat Aḥwāl Ṣāḥib al-Sharīʿa collect reports of the Prophet’s signs along with chronology of his life. Al-Bayhaqī’s is the largest and includes chains and critical comments. Works with this title also exist by al-Firyābī, al-Ḥākim (not in print) and others. Al-Māwardī’s Aʿlām al-Nubuwwa takes a more theological approach."],
    de: ["Welche Autoren schrieben die bekanntesten Werke mit dem Titel ‚Dalāʾil an-Nubuwwa‘ (Beweise der Prophetie)?", ["Abū Nuʿaim al-Iṣbahānī (gest. 430 n. H.) und al-Baihaqī (gest. 458 n. H.), wobei Letzterer am umfassendsten ist und auf frühe Maġāzī zurückgreift", "Al-Buḫārī und Muslim", "Ibn Hišām und al-Wāqidī", "Ibn Mālik und Sībawaih"], "Abū Nuʿaims Dalāʾil an-Nubuwwa und al-Baihaqīs Dalāʾil an-Nubuwwa wa-Maʿrifat Aḥwāl Ṣāḥib aš-Šarīʿa sammeln Berichte über die Zeichen des Propheten samt Chronologie seines Lebens. Al-Baihaqīs ist das größte und enthält Ketten und kritische Anmerkungen. Werke mit diesem Titel gibt es auch von al-Firyābī, al-Ḥākim (nicht gedruckt) und anderen. Al-Māwardīs Aʿlām an-Nubuwwa verfolgt einen eher theologischen Ansatz."],
    ar: ["من مؤلفو أشهر الكتب المعنونة «دلائل النبوة»؟", ["أبو نعيم الأصبهاني (ت 430هـ) والبيهقي (ت 458هـ) وكتاب الأخير أوسع ويعتمد على المغازي المبكرة", "البخاري ومسلم", "ابن هشام والواقدي", "ابن مالك وسيبويه"], "جمع «دلائل النبوة» لأبي نعيم و«دلائل النبوة ومعرفة أحوال صاحب الشريعة» للبيهقي أخبار آيات النبي ﷺ مع ترتيب زمني لسيرته، وكتاب البيهقي أوسعها فيه أسانيد وتعليقات نقدية، وللفريابي والحاكم (غير مطبوع) وغيرهما كتب بالعنوان نفسه، أما «أعلام النبوة» للماوردي فمنهجه أقرب إلى الكلام."] },

  { id: "xsr-033", s: "seerah", g: 4, d: 6, t: ["al-sira-al-halabiyya", "later-works", "shamail-commentary"], src: "Ibn Sayyid al-Nās, ʿUyūn al-Athar; Ibn Kathīr, al-Sīra al-Nabawiyya; al-Suhaylī, al-Rawḍ al-Unuf; Ibn al-Qayyim, Zād al-Maʿād",
    en: ["Which statement correctly matches later biographical works with their authors?", ["al-Suhaylī: al-Rawḍ al-Unuf (a commentary on Ibn Hishām); Ibn Sayyid al-Nās: ʿUyūn al-Athar; Ibn al-Qayyim: Zād al-Maʿād", "al-Suhaylī: Zād al-Maʿād; Ibn Sayyid al-Nās: al-Rawḍ al-Unuf; Ibn al-Qayyim: ʿUyūn al-Athar", "All three wrote the same book", "None of them wrote on the sīra"], "Al-Suhaylī (d. 581 AH) wrote al-Rawḍ al-Unuf as a commentary on Ibn Hishām’s Sīra with linguistic, legal and historical notes. Ibn Sayyid al-Nās (d. 734 AH) wrote ʿUyūn al-Athar, a hadith-critical compilation of the sīra, and Ibn al-Qayyim (d. 751 AH) wrote Zād al-Maʿād fī Hady Khayr al-ʿIbād, a work of guidance and rulings drawn from the Prophet’s life."],
    de: ["Welche Aussage ordnet spätere biografische Werke ihren Autoren richtig zu?", ["As-Suhailī: ar-Rauḍ al-Unuf (ein Kommentar zu Ibn Hišām); Ibn Sayyid an-Nās: ʿUyūn al-Aṯar; Ibn al-Qayyim: Zād al-Maʿād", "As-Suhailī: Zād al-Maʿād; Ibn Sayyid an-Nās: ar-Rauḍ al-Unuf; Ibn al-Qayyim: ʿUyūn al-Aṯar", "Alle drei schrieben dasselbe Buch", "Keiner von ihnen schrieb über die Sīra"], "As-Suhailī (gest. 581 n. H.) schrieb ar-Rauḍ al-Unuf als Kommentar zu Ibn Hišāms Sīra mit sprachlichen, rechtlichen und historischen Anmerkungen. Ibn Sayyid an-Nās (gest. 734 n. H.) schrieb ʿUyūn al-Aṯar, eine hadithkritische Zusammenstellung der Sīra, und Ibn al-Qayyim (gest. 751 n. H.) schrieb Zād al-Maʿād fī Hadī Ḫair al-ʿIbād, ein Werk der Rechtleitung und Vorschriften aus dem Leben des Propheten."],
    ar: ["أي عبارة تقرن مؤلفات السيرة المتأخرة بأصحابها على الوجه الصحيح؟", ["السهيلي: الروض الأنف (شرح على ابن هشام)؛ ابن سيد الناس: عيون الأثر؛ ابن القيم: زاد المعاد", "السهيلي: زاد المعاد؛ ابن سيد الناس: الروض الأنف؛ ابن القيم: عيون الأثر", "الثلاثة ألفوا كتابًا واحدًا", "لم يكتب أحدهم في السيرة"], "ألّف السهيلي (ت 581هـ) «الروض الأنف» شرحًا لسيرة ابن هشام بفوائد لغوية وفقهية وتاريخية، وألّف ابن سيد الناس (ت 734هـ) «عيون الأثر» وهو جمع للسيرة بنقد حديثي، وألّف ابن القيم (ت 751هـ) «زاد المعاد في هدي خير العباد» وهو كتاب هدي وأحكام من حياة النبي ﷺ."] },

  { id: "xsr-034", s: "seerah", g: 4, d: 7, t: ["methodology", "weak-reports-seerah", "ahmad-ibn-hanbal"], tr: ["comparative"], src: "Ibn Rajab, Sharḥ ʿIlal al-Tirmidhī; al-Khaṭīb al-Baghdādī, al-Kifāya; al-Bayhaqī, Dalāʾil al-Nubuwwa (introduction on tasāhul)",
    en: ["What method did some hadith scholars attribute to themselves regarding reports on the sīra and maghāzī, as opposed to rulings?", ["They were more lenient with chains in sīra, history and virtues than in reports on halal and haram, while still criticising what was fabricated", "They accepted every report without chains", "They refused to narrate anything from the maghāzī", "They required ten narrators for every historical report"], "Some scholars, including those cited by al-Bayhaqī and Ibn Rajab, were more lenient (tasāhul) in the chains of reports on virtues, sīra and history than in those about rulings. This does not mean fabricated reports were accepted, and scholars warned about reports from known liars. Modern researchers debate how far historical reports should be tested by hadith rules, with many applying hadith criticism together with historical criticism."],
    de: ["Welche Methode schrieben sich manche Hadithgelehrte hinsichtlich der Berichte über Sīra und Maġāzī im Gegensatz zu Rechtsvorschriften zu?", ["Sie waren bei Ketten in Sīra, Geschichte und Vorzügen nachsichtiger als bei Berichten über Erlaubtes und Verbotenes, kritisierten aber weiterhin Erfundenes", "Sie nahmen jeden Bericht ohne Ketten an", "Sie weigerten sich, irgendetwas aus den Maġāzī zu überliefern", "Sie verlangten zehn Überlieferer für jeden historischen Bericht"], "Manche Gelehrte, auch bei al-Baihaqī und Ibn Raǧab angeführte, waren bei den Ketten von Berichten über Vorzüge, Sīra und Geschichte nachsichtiger (tasāhul) als bei solchen über Rechtsvorschriften. Das heißt nicht, dass erfundene Berichte angenommen wurden, und Gelehrte warnten vor Berichten bekannter Lügner. Moderne Forscher debattieren, wie weit historische Berichte nach Hadithregeln zu prüfen sind, wobei viele Hadithkritik mit historischer Kritik verbinden."],
    ar: ["ما المنهج الذي نسبه بعض المحدثين لأنفسهم في أخبار السيرة والمغازي بخلاف الأحكام؟", ["كانوا أشد تساهلًا في الأسانيد في السيرة والتاريخ والفضائل منهم في أخبار الحلال والحرام، مع نقد الموضوع", "قبلوا كل خبر بلا سند", "رفضوا رواية أي شيء من المغازي", "اشترطوا عشرة رواة لكل خبر تاريخي"], "تساهل بعض العلماء ممن يذكرهم البيهقي وابن رجب في أسانيد أخبار الفضائل والسير والتاريخ أكثر من أخبار الأحكام، ولا يعني ذلك قبول الموضوع وقد حذروا من أخبار الكذابين المعروفين، ويناقش الباحثون المعاصرون مدى تطبيق قواعد الحديث على الأخبار التاريخية ويجمع كثيرون بين نقد الحديث والنقد التاريخي."] },

  { id: "xsr-035", s: "seerah", g: 4, d: 6, t: ["madina", "mosque", "masjid-nabawi"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-ṣalāh (bina’ al-masjid); Ibn Hishām, al-Sīra; Ibn Saʿd, al-Ṭabaqāt",
    en: ["How do the sound reports describe the first building of the Prophet’s Mosque in Madīna?", ["It was built on land bought from two orphans, with walls of mud-brick, palm-trunk pillars and a roof of palm fronds, and the Prophet ﷺ himself worked on it", "It was built of marble by Byzantine craftsmen", "It was built on the site of the Kaʿba", "It was built with a minaret and a dome from the start"], "In al-Bukhārī’s report from Anas, the Prophet ﷺ chose the site where his she-camel knelt, an area owned by two orphans, Sahl and Suhayl, whose price was paid, and the Muslims built it from mud-brick with palm trunks as pillars and palm leaves as roof. The Prophet ﷺ carried bricks with the Companions. The qibla was first facing Jerusalem and later changed. Dome and minarets were later additions."],
    de: ["Wie beschreiben die gesunden Berichte den ersten Bau der Moschee des Propheten in Medina?", ["Sie wurde auf von zwei Waisen gekauftem Land gebaut, mit Lehmziegelwänden, Palmstammpfeilern und einem Dach aus Palmwedeln, und der Prophet ﷺ arbeitete selbst daran", "Sie wurde von byzantinischen Handwerkern aus Marmor gebaut", "Sie wurde an der Stelle der Kaaba gebaut", "Sie wurde von Anfang an mit Minarett und Kuppel gebaut"], "Im Bericht von Anas bei al-Buḫārī wählte der Prophet ﷺ die Stelle, an der seine Kamelstute niederkniete, ein Gelände zweier Waisen, Sahl und Suhail, deren Preis bezahlt wurde, und die Muslime bauten sie aus Lehmziegeln mit Palmstämmen als Pfeilern und Palmwedeln als Dach. Der Prophet ﷺ trug mit den Gefährten Ziegel. Die Qibla war zunächst nach Jerusalem gerichtet und wurde später geändert. Kuppel und Minarette kamen später hinzu."],
    ar: ["كيف تصف الروايات الصحيحة البناء الأول للمسجد النبوي في المدينة؟", ["بُني على أرض اشتراها من يتيمين، بجدران من اللبن وأعمدة من جذوع النخل وسقف من الجريد، وشارك النبي ﷺ في العمل", "بناه صناع روم من الرخام", "بُني في موضع الكعبة", "بُني بمئذنة وقبة منذ البداية"], "في حديث أنس في البخاري اختار النبي ﷺ الموضع الذي بركت فيه ناقته وهو لغلامين يتيمين سهل وسهيل فدفع ثمنه، وبنى المسلمون المسجد باللبن وجعلوا عمده جذوع النخل وسقفه الجريد، وحمل النبي ﷺ اللبن مع الصحابة، وكانت القبلة أولًا إلى بيت المقدس ثم تحولت، وأضيفت القبة والمآذن لاحقًا."] },

  { id: "xsr-036", s: "seerah", g: 4, d: 7, t: ["qibla", "change", "chronology"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-īmān and Kitāb al-ṣalāh (al-Barā’); Ibn Ḥajar, Fatḥ al-Bārī; Ibn Kathīr, Tafsīr, on sūrat al-Baqara",
    en: ["What do the reports say about the change of the qibla, including the debated timing?", ["The Prophet ﷺ prayed towards Jerusalem for about sixteen or seventeen months after the Hijra and then was commanded to face the Kaʿba; al-Barā’ says sixteen or seventeen months and other reports mention differing months; the date is debated among historians", "The qibla was never changed", "It changed on the first day of the Hijra", "It changed after the conquest of Makka"], "In al-Barā’’s report in al-Bukhārī, the Muslims prayed towards Bayt al-Maqdis for sixteen or seventeen months before the verse about turning the face to al-Masjid al-Ḥarām. Ibn Ḥajar discusses the differing reports on the month (Rajab, Shaʿbān or others) and the first prayer after the change. The Prophet ﷺ used to love facing the Kaʿba, the report says."],
    de: ["Was sagen die Berichte über den Wechsel der Qibla, einschließlich des umstrittenen Zeitpunkts?", ["Der Prophet ﷺ betete nach der Hidschra etwa sechzehn oder siebzehn Monate in Richtung Jerusalem und erhielt dann den Befehl, sich der Kaaba zuzuwenden; al-Barāʾ sagt sechzehn oder siebzehn Monate, andere Berichte nennen abweichende Monate; das Datum ist unter Historikern umstritten", "Die Qibla wurde nie gewechselt", "Sie wechselte am ersten Tag der Hidschra", "Sie wechselte nach der Eroberung Mekkas"], "Im Bericht von al-Barāʾ bei al-Buḫārī beteten die Muslime sechzehn oder siebzehn Monate in Richtung Bait al-Maqdis, bevor der Vers über das Wenden des Gesichts zu al-Masǧid al-Ḥarām herabkam. Ibn Ḥaǧar erörtert die abweichenden Berichte über den Monat (Raǧab, Šaʿbān oder andere) und das erste Gebet nach dem Wechsel. Der Prophet ﷺ liebte es, so sagt der Bericht, sich der Kaaba zuzuwenden."],
    ar: ["ماذا تقول الروايات عن تحويل القبلة ومنها الخلاف في توقيته؟", ["صلى النبي ﷺ نحو بيت المقدس نحو ستة عشر أو سبعة عشر شهرًا بعد الهجرة ثم أُمر بالتوجه إلى الكعبة، وتختلف الروايات في الشهر، والتاريخ محل نقاش بين المؤرخين", "لم تتحول القبلة أبدًا", "تحولت في أول يوم من الهجرة", "تحولت بعد فتح مكة"], "في حديث البراء في البخاري صلى المسلمون نحو بيت المقدس ستة عشر أو سبعة عشر شهرًا قبل نزول الآية بتولية الوجه شطر المسجد الحرام، ويناقش ابن حجر اختلاف الروايات في الشهر (رجب أو شعبان أو غيرهما) وفي أول صلاة بعد التحويل، وكان النبي ﷺ يحب أن يتوجه إلى الكعبة كما تقول الرواية."] },

  { id: "xsr-037", s: "seerah", g: 4, d: 6, t: ["mutah-expedition", "commanders", "khalid"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-maghāzī (Ghazwat Muʾta); Ibn Hishām, al-Sīra; al-Ṭabarī, Taʾrīkh",
    en: ["What do the sound reports say about the expedition to Muʾta (8 AH), including its three commanders and Khālid ibn al-Walīd?", ["The Prophet ﷺ named Zayd ibn Ḥāritha, then Jaʿfar, then ʿAbd Allāh ibn Rawāḥa as successive commanders; all three fell, the standard was taken by Khālid, whom the Prophet ﷺ called a sword of God, and the army withdrew", "The army was led by Abū Bakr and won a great victory", "It was a naval battle against Persia", "It was led by the Prophet ﷺ himself"], "In al-Bukhārī, the Prophet ﷺ appointed Zayd ibn Ḥāritha, and if he fell, Jaʿfar, and if he fell, ʿAbd Allāh ibn Rawāḥa. All three were killed. The Prophet ﷺ informed the people in Madīna of the deaths with tears and said the flag was taken by one of God’s swords (Khālid) until God gave victory. Scholars discuss whether Khālid’s withdrawal was a tactical retreat or an outcome described as a victory in the reports."],
    de: ["Was sagen die gesunden Berichte über den Feldzug nach Muʾta (8 n. H.), einschließlich seiner drei Befehlshaber und Ḫālid ibn al-Walīds?", ["Der Prophet ﷺ ernannte Zaid ibn Ḥāriṯa, dann Ǧaʿfar, dann ʿAbd Allāh ibn Rawāḥa als aufeinanderfolgende Befehlshaber; alle drei fielen, die Fahne nahm Ḫālid, den der Prophet ﷺ ein Schwert Gottes nannte, und das Heer zog sich zurück", "Das Heer wurde von Abū Bakr geführt und errang einen großen Sieg", "Es war eine Seeschlacht gegen Persien", "Er wurde vom Propheten ﷺ selbst geführt"], "Bei al-Buḫārī ernannte der Prophet ﷺ Zaid ibn Ḥāriṯa, und falls er fiele, Ǧaʿfar, und falls er fiele, ʿAbd Allāh ibn Rawāḥa. Alle drei wurden getötet. Der Prophet ﷺ teilte den Leuten in Medina unter Tränen die Tode mit und sagte, die Fahne habe eines der Schwerter Gottes (Ḫālid) genommen, bis Gott den Sieg gab. Gelehrte erörtern, ob Ḫālids Rückzug ein taktischer Rückzug war oder ein in den Berichten als Sieg beschriebenes Ergebnis."],
    ar: ["ماذا تقول الروايات الصحيحة عن غزوة مؤتة (8هـ) وقادتها الثلاثة وخالد بن الوليد؟", ["أمّر النبي ﷺ زيد بن حارثة ثم جعفرًا ثم عبد الله بن رواحة فاستشهدوا جميعًا وأخذ الراية خالد الذي سماه النبي ﷺ سيفًا من سيوف الله وانحاز الجيش", "قاد الجيش أبو بكر وانتصر نصرًا عظيمًا", "كانت معركة بحرية ضد الفرس", "قادها النبي ﷺ بنفسه"], "في البخاري أمّر النبي ﷺ زيد بن حارثة فإن قُتل فجعفر فإن قُتل فعبد الله بن رواحة، فقُتلوا كلهم، ونعاهم النبي ﷺ للناس في المدينة وعيناه تذرفان وقال أخذ الراية سيف من سيوف الله (خالد) حتى فتح الله عليهم، ويناقش العلماء هل كان انحياز خالد انسحابًا تكتيكيًّا أو نتيجة تصفها الروايات بالفتح."] },

  { id: "xsr-038", s: "seerah", g: 4, d: 7, t: ["dream-people", "bani-nadir", "exile"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-maghāzī; Ibn Hishām, al-Sīra; Ibn Ḥajar, Fatḥ al-Bārī",
    en: ["What disagreement exists about the date of Banū al-Naḍīr’s expulsion relative to Uḥud?", ["Ibn Isḥāq placed it after Uḥud (in 4 AH), while al-Zuhrī, as reported by ʿUrwa and cited in al-Bukhārī, placed it before Uḥud, six months after Badr", "All sources place it after the conquest of Makka", "All sources place it before the Hijra", "It never happened"], "Ibn Isḥāq puts the expulsion of Banū al-Naḍīr after the events of Biʾr Maʿūna in Rabīʿ al-Awwal of 4 AH. Mūsā ibn ʿUqba, from al-Zuhrī and ʿUrwa, puts it before Uḥud, around six months after Badr, and al-Bukhārī gives the latter without choosing. Ibn Ḥajar discusses the difference and the placing of the revelation of sūrat al-Ḥashr in connection with it."],
    de: ["Welche Meinungsverschiedenheit besteht über das Datum der Vertreibung der Banū an-Naḍīr im Verhältnis zu Uḥud?", ["Ibn Isḥāq setzte sie nach Uḥud (4 n. H.), während az-Zuhrī, von ʿUrwa berichtet und bei al-Buḫārī angeführt, sie vor Uḥud setzte, sechs Monate nach Badr", "Alle Quellen setzen sie nach der Eroberung Mekkas", "Alle Quellen setzen sie vor die Hidschra", "Sie fand nie statt"], "Ibn Isḥāq setzt die Vertreibung der Banū an-Naḍīr nach den Ereignissen von Biʾr Maʿūna im Rabīʿ al-Awwal des Jahres 4 n. H. Mūsā ibn ʿUqba setzt sie von az-Zuhrī und ʿUrwa her vor Uḥud, etwa sechs Monate nach Badr, und al-Buḫārī bringt Letzteres, ohne zu wählen. Ibn Ḥaǧar erörtert den Unterschied und die Einordnung der Offenbarung der Sure al-Ḥašr im Zusammenhang damit."],
    ar: ["ما الخلاف في زمن إجلاء بني النضير بالنسبة إلى أحد؟", ["جعله ابن إسحاق بعد أحد (سنة 4هـ) بينما جعله الزهري عن عروة، ويذكره البخاري، قبل أحد بعد بدر بستة أشهر", "تضعه المصادر كلها بعد فتح مكة", "تضعه المصادر كلها قبل الهجرة", "لم يحدث"], "جعل ابن إسحاق إجلاء بني النضير بعد بئر معونة في ربيع الأول سنة 4هـ، وجعله موسى بن عقبة عن الزهري وعروة قبل أحد بنحو ستة أشهر من بدر، وأورد البخاري الثاني دون ترجيح، وناقش ابن حجر الاختلاف وموضع نزول سورة الحشر في ذلك."] },

  { id: "xsr-039", s: "seerah", g: 4, d: 6, t: ["names", "titles", "ahmad-muhammad"], src: "Ibn al-ʿArabī, ʿĀriḍat al-Aḥwadhī; al-Qāḍī ʿIyāḍ, al-Shifā; al-Bukhārī, Ṣaḥīḥ (Jubayr ibn Muṭʿim: names of the Prophet)",
    en: ["Which names of the Prophet ﷺ are given in the hadith of Jubayr ibn Muṭʿim, and what is the status of lists of 'a thousand names'?", ["Muḥammad, Aḥmad, al-Māḥī, al-Ḥāshir and al-ʿĀqib; the long lists of names that later authors produced are not matched by sound reports", "Only Abū al-Qāsim", "Only Muṣṭafā and Ṭāhā", "Ibrāhīm, Ismāʿīl and Isḥāq"], "In the Ṣaḥīḥayn, the Prophet ﷺ is reported to have said he has names: Muḥammad, Aḥmad, al-Māḥī (the one by whom disbelief is wiped out), al-Ḥāshir (before whom people are gathered) and al-ʿĀqib (the last of the prophets). Later authors, such as in Dalāʾil al-Khayrāt, gave much longer lists. Ibn al-ʿArabī and al-Qāḍī ʿIyāḍ discussed the names in the sound reports, with Ibn al-ʿArabī giving a long list from the Quran and Sunna."],
    de: ["Welche Namen des Propheten ﷺ nennt der Hadith von Ǧubair ibn Muṭʿim, und welchen Status haben Listen mit ‚tausend Namen‘?", ["Muḥammad, Aḥmad, al-Māḥī, al-Ḥāšir und al-ʿĀqib; die langen Namenslisten späterer Autoren werden durch gesunde Berichte nicht gedeckt", "Nur Abū l-Qāsim", "Nur Muṣṭafā und Ṭāhā", "Ibrāhīm, Ismāʿīl und Isḥāq"], "In den Ṣaḥīḥain wird berichtet, der Prophet ﷺ habe gesagt, er habe Namen: Muḥammad, Aḥmad, al-Māḥī (der, durch den der Unglaube ausgelöscht wird), al-Ḥāšir (vor dem die Menschen versammelt werden) und al-ʿĀqib (der letzte der Propheten). Spätere Autoren, etwa in Dalāʾil al-Ḫairāt, gaben viel längere Listen. Ibn al-ʿArabī und al-Qāḍī ʿIyāḍ erörterten die Namen in den gesunden Berichten, wobei Ibn al-ʿArabī eine lange Liste aus Koran und Sunna gab."],
    ar: ["ما الأسماء التي وردت للنبي ﷺ في حديث جبير بن مطعم وما حال قوائم «ألف اسم»؟", ["محمد وأحمد والماحي والحاشر والعاقب، والقوائم الطويلة التي وضعها المتأخرون لا تقابلها أخبار صحيحة", "أبو القاسم فقط", "مصطفى وطه فقط", "إبراهيم وإسماعيل وإسحاق"], "في الصحيحين أن النبي ﷺ قال إن له أسماء: محمد وأحمد والماحي الذي يمحو الله به الكفر والحاشر الذي يُحشر الناس على قدمه والعاقب أي آخر الأنبياء، وأورد متأخرون كصاحب «دلائل الخيرات» قوائم أطول، وناقش ابن العربي والقاضي عياض الأسماء في الصحاح وذكر ابن العربي قائمة طويلة من القرآن والسنة."] },

  { id: "xsr-040", s: "seerah", g: 4, d: 7, t: ["methodology", "orientalists", "historiography"], tr: ["comparative"], src: "Ibn Khaldūn, Muqaddima; al-Dhahabī, Siyar Aʿlām al-Nubalāʾ; Akram Ḍiyāʾ al-ʿUmarī, al-Sīra al-Nabawiyya al-Ṣaḥīḥa; Ibn Ḥajar, Fatḥ al-Bārī",
    en: ["Which approach to the sources of the sīra is taken in al-ʿUmarī’s al-Sīra al-Nabawiyya al-Ṣaḥīḥa, and how does it relate to classical practice?", ["It applies hadith criticism to reports of the sīra to write a biography from authenticated reports, following the older distinction between Ṣaḥīḥ-grade reports and the general maghāzī material", "It rejects all hadith in favour of poetry", "It translates the Gospels", "It is a commentary on Ibn Khaldūn’s Muqaddima"], "Akram Ḍiyāʾ al-ʿUmarī (20th century) wrote al-Sīra al-Nabawiyya al-Ṣaḥīḥa to collect authenticated reports on the Prophet’s life using the rules of hadith criticism, building on the classical distinction between works of sīra (such as Ibn Isḥāq’s) and the sound reports in the Ṣaḥīḥayn and other collections. Other modern scholars, in contrast, argue that historical criticism should be used in addition to hadith methods."],
    de: ["Welchen Ansatz zu den Quellen der Sīra verfolgt al-ʿUmarīs as-Sīra an-Nabawiyya aṣ-Ṣaḥīḥa, und wie verhält er sich zur klassischen Praxis?", ["Er wendet Hadithkritik auf Berichte der Sīra an, um eine Biografie aus beglaubigten Berichten zu schreiben, im Anschluss an die ältere Unterscheidung zwischen Berichten ṣaḥīḥ-Grades und dem allgemeinen Maġāzī-Stoff", "Er verwirft alle Hadithe zugunsten der Dichtung", "Er übersetzt die Evangelien", "Er ist ein Kommentar zu Ibn Ḫaldūns Muqaddima"], "Akram Ḍiyāʾ al-ʿUmarī (20. Jh.) schrieb as-Sīra an-Nabawiyya aṣ-Ṣaḥīḥa, um beglaubigte Berichte über das Leben des Propheten nach den Regeln der Hadithkritik zu sammeln, aufbauend auf der klassischen Unterscheidung zwischen Sīra-Werken (wie dem von Ibn Isḥāq) und den gesunden Berichten in den Ṣaḥīḥain und anderen Sammlungen. Andere moderne Gelehrte argumentieren dagegen, dass zusätzlich historische Kritik angewandt werden solle."],
    ar: ["ما المنهج الذي اتخذه كتاب «السيرة النبوية الصحيحة» لأكرم ضياء العمري في مصادر السيرة وصلته بالممارسة الكلاسيكية؟", ["تطبيق قواعد نقد الحديث على أخبار السيرة لكتابة سيرة من الروايات الثابتة، تبعًا للتمييز القديم بين الأخبار الصحيحة وعامة مادة المغازي", "رفض كل الأحاديث لصالح الشعر", "ترجمة الأناجيل", "شرح مقدمة ابن خلدون"], "ألّف أكرم ضياء العمري (القرن العشرين) «السيرة النبوية الصحيحة» ليجمع الأخبار الثابتة في حياة النبي ﷺ بقواعد نقد الحديث، بناءً على التمييز الكلاسيكي بين كتب السيرة (كسيرة ابن إسحاق) والروايات الصحيحة في الصحيحين وغيرهما، ويرى باحثون معاصرون آخرون ضرورة إضافة النقد التاريخي إلى منهج المحدثين."] },
];
